    return False

def list_newsgroups_gen(self, pattern=None):
    args = pattern
    (code, message) = self.command('LIST NEWSGROUPS', args)
    if code != 215:
        raise NNTPReplyError(code, message)
    for line in self.info_gen(code, message):
        parts = line.strip().split()
        (name, description) = (parts[0], '')
        if len(parts) > 1:
            description = parts[1]
        yield (name, description)

def confusion_matrix(self, metrics=None, thresholds=None):
    if metrics is None and thresholds is None:
        metrics = ['f1']
    if isinstance(metrics, list):
        metrics_list = metrics
    elif metrics is None:
        metrics_list = []
    else:
        metrics_list = [metrics]
    if isinstance(thresholds, list):
        thresholds_list = thresholds
    elif thresholds is None:
        thresholds_list = []
    else:
        thresholds_list = [thresholds]
    assert_is_type(thresholds_list, [numeric])
    assert_satisfies(thresholds_list, all((0 <= t <= 1 for t in thresholds_list)))
    if not all((m.lower() in H2OBinomialModelMetrics.max_metrics for m in metrics_list)):
        raise ValueError('The only allowable metrics are {}', ', '.join(H2OBinomialModelMetrics.max_metrics))
    metrics_thresholds = [self.find_threshold_by_max_metric(m) for m in metrics_list]
    for mt in metrics_thresholds:
        thresholds_list.append(mt)
    first_metrics_thresholds_offset = len(thresholds_list) - len(metrics_thresholds)
    thresh2d = self._metric_json['thresholds_and_metric_scores']
    actual_thresholds = [float(e[0]) for (i, e) in enumerate(thresh2d.cell_values)]
    cms = []
    for (i, t) in enumerate(thresholds_list):
        idx = self.find_idx_by_threshold(t)
        row = thresh2d.cell_values[idx]
        tns = row[11]
        fns = row[12]
        fps = row[13]
        tps = row[14]
        p = tps + fns
        n = tns + fps
        c0 = n - fps
        c1 = p - tps
        if t in metrics_thresholds:
            m = metrics_list[i - first_metrics_thresholds_offset]
            table_header = 'Confusion Matrix (Act/Pred) for max {} @ threshold = {}'.format(m, actual_thresholds[idx])
        else:
            table_header = 'Confusion Matrix (Act/Pred) @ threshold = {}'.format(actual_thresholds[idx])
        cms.append(ConfusionMatrix(cm=[[c0, fps], [c1, tps]], domains=self._metric_json['domain'], table_header=table_header))
    if len(cms) == 1:
        return cms[0]
    else:
        return cms

def _find_link(inst1, inst2, rel_id, phrase):
    metaclass1 = get_metaclass(inst1)
    metaclass2 = get_metaclass(inst2)
    if isinstance(rel_id, int):
        rel_id = 'R%d' % rel_id
    for ass in metaclass1.metamodel.associations:
        if ass.rel_id != rel_id:
            continue
        if ass.source_link.from_metaclass.kind == metaclass1.kind and ass.source_link.to_metaclass.kind == metaclass2.kind and (ass.source_link.phrase == phrase):
            return (inst1, inst2, ass)
        if ass.target_link.from_metaclass.kind == metaclass1.kind and ass.target_link.to_metaclass.kind == metaclass2.kind and (ass.target_link.phrase == phrase):
            return (inst2, inst1, ass)
    raise UnknownLinkException(metaclass1.kind, metaclass2.kind, rel_id, phrase)

