def call(self, url, func, data=None, headers=None, return_json=True, stream=False, retry=True, default_headers=True, quiet=False):
    if data is not None:
        if not isinstance(data, dict):
            data = json.dumps(data)
    heads = dict()
    if default_headers is True:
        heads = self.headers.copy()
    if headers is not None:
        if isinstance(headers, dict):
            heads.update(headers)
    response = func(url=url, headers=heads, data=data, verify=self._verify(), stream=stream)
    if response.status_code in [500, 502]:
        bot.error('Beep boop! %s: %s' % (response.reason, response.status_code))
        sys.exit(1)
    if response.status_code == 404:
        if quiet is False:
            bot.error('Beep boop! %s: %s' % (response.reason, response.status_code))
        sys.exit(1)
    if response.status_code == 401:
        if retry is True and hasattr(self, '_update_token'):
            self._update_token(response)
            return self._call(url, func, data=data, headers=headers, return_json=return_json, stream=stream, retry=False)
        bot.error('Your credentials are expired! %s: %s' % (response.reason, response.status_code))
        sys.exit(1)
    elif response.status_code == 200:
        if return_json:
            try:
                response = response.json()
            except ValueError:
                bot.error('The server returned a malformed response.')
                sys.exit(1)
    return response

