def run(self, data_loaders, workflow, max_epochs, **kwargs):
    assert isinstance(data_loaders, list)
    assert mmcv.is_list_of(workflow, tuple)
    assert len(data_loaders) == len(workflow)
    self._max_epochs = max_epochs
    work_dir = self.work_dir if self.work_dir is not None else 'NONE'
    self.logger.info('Start running, host: %s, work_dir: %s', get_host_info(), work_dir)
    self.logger.info('workflow: %s, max: %d epochs', workflow, max_epochs)
    self.call_hook('before_run')
    while self.epoch < max_epochs:
        for (i, flow) in enumerate(workflow):
            (mode, epochs) = flow
            if isinstance(mode, str):
                if not hasattr(self, mode):
                    raise ValueError('runner has no method named "{}" to run an epoch'.format(mode))
                epoch_runner = getattr(self, mode)
            elif callable(mode):
                epoch_runner = mode
            else:
                raise TypeError('mode in workflow must be a str or callable function, not {}'.format(type(mode)))
            for _ in range(epochs):
                if mode == 'train' and self.epoch >= max_epochs:
                    return
                epoch_runner(data_loaders[i], **kwargs)
    time.sleep(1)
    self.call_hook('after_run')

def _enforce_no_overlap(self, start_at=0):
    i = start_at
    while i + 1 < len(self.data):
        if self.data[i][1] >= self.data[i + 1][0]:
            if self.data[i][1] < self.data[i + 1][1]:
                self.data[i][1] = self.data[i + 1][1]
            del self.data[i + 1]
        i += 1

def reconstruct(self, inputs, samples=1, sample_static=False, sample_dynamic=False, swap_static=False, swap_dynamic=False, fix_static=False, fix_dynamic=False):
    batch_size = tf.shape(input=inputs)[-5]
    length = len(tf.unstack(inputs, axis=-4))
    features = self.compressor(inputs)
    if sample_static:
        (static_sample, _) = self.sample_static_prior(samples, batch_size, fix_static)
    else:
        (static_sample, _) = self.sample_static_posterior(features, samples)
    if swap_static:
        static_sample = tf.reverse(static_sample, axis=[1])
    if sample_dynamic:
        (dynamic_sample, _) = self.sample_dynamic_prior(samples, batch_size, length, fix_dynamic)
    else:
        (dynamic_sample, _) = self.sample_dynamic_posterior(features, samples, static_sample)
    if swap_dynamic:
        dynamic_sample = tf.reverse(dynamic_sample, axis=[1])
    likelihood = self.decoder((dynamic_sample, static_sample))
    return likelihood

