def memoize_single_arg(f):
    memo = {}

    @wraps(f)
    def memoized_f(arg):
        try:
            return memo[arg]
        except KeyError:
            result = memo[arg] = f(arg)
            return result
    return memoized_f

def filter_contigs(self, *comparisons):
    self.filtered_ids = []
    self.report = {}
    gc_filters = [['gc_prop', '>=', self.min_gc], ['gc_prop', '<=', 1 - self.min_gc]]
    self.filters = list(comparisons) + gc_filters
    logger.debug('Filtering contigs using filters: {}'.format(self.filters))
    for (contig_id, contig) in self.contigs.items():
        for (key, op, value) in list(comparisons) + gc_filters:
            if not self._test_truth(contig[key], op, value):
                self.filtered_ids.append(contig_id)
                self.report[contig_id] = '{}/{}/{}'.format(key, contig[key], value)
                break
            else:
                self.report[contig_id] = 'pass'

def visit_Include(self, node, frame):
    if node.with_context:
        self.unoptimize_scope(frame)
    if node.ignore_missing:
        self.writeline('try:')
        self.indent()
    func_name = 'get_or_select_template'
    if isinstance(node.template, nodes.Const):
        if isinstance(node.template.value, string_types):
            func_name = 'get_template'
        elif isinstance(node.template.value, (tuple, list)):
            func_name = 'select_template'
    elif isinstance(node.template, (nodes.Tuple, nodes.List)):
        func_name = 'select_template'
    self.writeline('template = environment.%s(' % func_name, node)
    self.visit(node.template, frame)
    self.write(', %r)' % self.name)
    if node.ignore_missing:
        self.outdent()
        self.writeline('except TemplateNotFound:')
        self.indent()
        self.writeline('pass')
        self.outdent()
        self.writeline('else:')
        self.indent()
    if node.with_context:
        self.writeline('for event in template.root_render_func(template.new_context(context.parent, True, locals())):')
    else:
        self.writeline('for event in template.module._body_stream:')
    self.indent()
    self.simple_write('event', frame)
    self.outdent()
    if node.ignore_missing:
        self.outdent()

def _convert(self, args):
    if args.find(',') > -1:
        (b, a) = args.replace('(', '').replace(')', '').split(',')
        a = chr(int(a) + 65)
        b = str(int(b) + 1)
        return a + b
    else:
        a = str(int(args[1:2]) - 1)
        b = str(ord(args[0:1].upper()) - 65)
        return '(' + a + ',' + b + ')'

