def check_spec(self, pos_args, kwargs=None):
    if kwargs is None:
        kwargs = {}
    if self.varargs is not None or self.kwargs is not None:
        raise InternalError('check_spec cannot be called on a function that takes *args or **kwargs')
    missing = object()
    arg_vals = [missing] * len(self.arg_names)
    kw_indices = {name: i for (i, name) in enumerate(self.arg_names)}
    for (i, arg) in enumerate(pos_args):
        if i >= len(arg_vals):
            raise ArgumentError('Too many positional arguments, first excessive argument=%s' % str(arg))
        arg_vals[i] = arg
    for (arg, val) in kwargs.items():
        index = kw_indices.get(arg)
        if index is None:
            raise ArgumentError('Cannot find argument by name: %s' % arg)
        if arg_vals[index] is not missing:
            raise ValidationError('Argument %s passed twice' % arg)
        arg_vals[index] = val
    if len(self.arg_defaults) > 0:
        for i in range(0, len(self.arg_defaults)):
            neg_index = -len(self.arg_defaults) + i
            if arg_vals[neg_index] is missing:
                arg_vals[neg_index] = self.arg_defaults[i]
    if missing in arg_vals:
        index = arg_vals.index(missing)
        raise ArgumentError('Missing a required argument (position: %d, name: %s)' % (index, self.arg_names[index]))
    return {name: val for (name, val) in zip(self.arg_names, arg_vals)}

def _compute_nfps_uniform(cum_counts, sizes):
    nfps = np.zeros((len(sizes), len(sizes)))
    for l in range(len(sizes)):
        for u in range(l, len(sizes)):
            nfps[l, u] = _compute_nfp_uniform(l, u, cum_counts, sizes)
    return nfps

def eval_hook(self, name: str, ctx: list) -> Node:
    if name not in self.__class__._hooks:
        self.diagnostic.notify(error.Severity.ERROR, 'Unknown hook : %s' % name, error.LocationInfo.from_stream(self._stream, is_error=True))
        raise self.diagnostic
    self._lastRule = '#' + name
    res = self.__class__._hooks[name](self, *ctx)
    if type(res) is not bool:
        raise TypeError("Your hook %r didn't return a bool value" % name)
    return res

def _compute_fano_factor(spike_res, neuron_id, time_window, start_time, end_time):
    assert end_time >= start_time + time_window
    bins = (end_time - start_time) / time_window
    bins = int(np.floor(bins))
    binned_spikes = np.zeros(bins)
    spike_array_neuron = spike_res.t[spike_res.i == neuron_id]
    for bin in range(bins):
        lower_time = start_time + time_window * bin
        upper_time = start_time + time_window * (bin + 1)
        spike_array_interval = spike_array_neuron[spike_array_neuron >= lower_time]
        spike_array_interval = spike_array_interval[spike_array_interval < upper_time]
        spikes = len(spike_array_interval)
        binned_spikes[bin] = spikes
    var = np.var(binned_spikes)
    avg = np.mean(binned_spikes)
    if avg > 0:
        return var / float(avg)
    else:
        return 0

