def _local_sym_to_py_ast(ctx: GeneratorContext, node: Local, is_assigning: bool=False) -> GeneratedPyAST:
    assert node.op == NodeOp.LOCAL
    sym_entry = ctx.symbol_table.find_symbol(sym.symbol(node.name))
    assert sym_entry is not None
    if node.local == LocalType.FIELD:
        this_entry = ctx.symbol_table.find_symbol(ctx.current_this)
        assert this_entry is not None, 'Field type local must have this'
        return GeneratedPyAST(node=_load_attr(f'{this_entry.munged}.{sym_entry.munged}', ctx=ast.Store() if is_assigning else ast.Load()))
    else:
        return GeneratedPyAST(node=ast.Name(id=sym_entry.munged, ctx=ast.Store() if is_assigning else ast.Load()))

def add_refer(self, sym: sym.Symbol, var: Var) -> None:
    if not var.is_private:
        self._refers.swap(lambda s: s.assoc(sym, var))

def prior_sample(self, num_timesteps, initial_step=0, params_sample_shape=(), trajectories_sample_shape=(), seed=None):
    seed = distributions.SeedStream(seed, salt='StructuralTimeSeries_prior_sample')
    with tf.compat.v1.name_scope('prior_sample', values=[num_timesteps, params_sample_shape, trajectories_sample_shape]):
        param_samples = [p.prior.sample(params_sample_shape, seed=seed(), name=p.name) for p in self.parameters]
        model = self.make_state_space_model(num_timesteps=num_timesteps, initial_step=initial_step, param_vals=param_samples)
        return (model.sample(trajectories_sample_shape, seed=seed()), param_samples)

def _trj_load_trajectory(self, traj, as_new, load_parameters, load_derived_parameters, load_results, load_other_data, recursive, max_depth, with_run_information, with_meta_data, force):
    if as_new and (load_derived_parameters != pypetconstants.LOAD_NOTHING or load_results != pypetconstants.LOAD_NOTHING or load_other_data != pypetconstants.LOAD_NOTHING):
        raise ValueError('You cannot load a trajectory as new and load the derived parameters and results. Only parameters are allowed.')
    if as_new and load_parameters != pypetconstants.LOAD_DATA:
        raise ValueError('You cannot load the trajectory as new and not load the data of the parameters.')
    loadconstants = (pypetconstants.LOAD_NOTHING, pypetconstants.LOAD_SKELETON, pypetconstants.LOAD_DATA, pypetconstants.OVERWRITE_DATA)
    if not (load_parameters in loadconstants and load_derived_parameters in loadconstants and (load_results in loadconstants) and (load_other_data in loadconstants)):
        raise ValueError('Please give a valid option on how to load data. Options for `load_parameter`, `load_derived_parameters`, `load_results`, and `load_other_data` are %s. See function documentation for the semantics of the values.' % str(loadconstants))
    traj._stored = not as_new
    load_data = max(load_parameters, load_derived_parameters, load_results, load_other_data)
    if with_meta_data:
        self._trj_load_meta_data(traj, load_data, as_new, with_run_information, force)
    if load_parameters != pypetconstants.LOAD_NOTHING or load_derived_parameters != pypetconstants.LOAD_NOTHING or load_results != pypetconstants.LOAD_NOTHING or (load_other_data != pypetconstants.LOAD_NOTHING):
        self._logger.info('Loading trajectory `%s`.' % traj.v_name)
    else:
        self._logger.info('Checked meta data of trajectory `%s`.' % traj.v_name)
        return
    maximum_display_other = 10
    counter = 0
    for children in [self._trajectory_group._v_groups, self._trajectory_group._v_links]:
        for hdf5_group_name in children:
            hdf5_group = children[hdf5_group_name]
            child_name = hdf5_group._v_name
            load_subbranch = True
            if child_name == 'config':
                if as_new:
                    loading = pypetconstants.LOAD_NOTHING
                else:
                    loading = load_parameters
            elif child_name == 'parameters':
                loading = load_parameters
            elif child_name == 'results':
                loading = load_results
            elif child_name == 'derived_parameters':
                loading = load_derived_parameters
            elif child_name == 'overview':
                continue
            else:
                loading = load_other_data
                load_subbranch = False
            if loading == pypetconstants.LOAD_NOTHING:
                continue
            if load_subbranch:
                self._logger.info('Loading branch `%s` in mode `%s`.' % (child_name, str(loading)))
            else:
                if counter < maximum_display_other:
                    self._logger.info('Loading branch/node `%s` in mode `%s`.' % (child_name, str(loading)))
                elif counter == maximum_display_other:
                    self._logger.info('To many branchs or nodes at root for display. I will not inform you about loading anymore. Branches are loaded silently in the background. Do not worry, I will not freeze! Pinky promise!!!')
                counter += 1
            self._tree_load_sub_branch(traj, child_name, load_data=loading, with_links=True, recursive=recursive, max_depth=max_depth, _trajectory=traj, _as_new=as_new, _hdf5_group=self._trajectory_group)

def t_INCLUDE(self, t):
    next_token = self.lexer.token()
    lineno = next_token.lineno
    if isinstance(next_token.value, str):
        incfile = next_token.value.strip('"')
    else:
        raise QasmError('Invalid include: must be a quoted string.')
    if incfile in CORE_LIBS:
        incfile = os.path.join(CORE_LIBS_PATH, incfile)
    next_token = self.lexer.token()
    if next_token is None or next_token.value != ';':
        raise QasmError('Invalid syntax, missing ";" at line', str(lineno))
    if not os.path.exists(incfile):
        raise QasmError('Include file %s cannot be found, line %s, file %s' % (incfile, str(next_token.lineno), self.filename))
    self.push(incfile)
    return self.lexer.token()

