def read(self, input_buffer, kmip_version=enums.KMIPVersion.KMIP_1_0):
    super(CreateKeyPairRequestPayload, self).read(input_buffer, kmip_version=kmip_version)
    local_buffer = utils.BytearrayStream(input_buffer.read(self.length))
    if kmip_version < enums.KMIPVersion.KMIP_2_0:
        if self.is_tag_next(enums.Tags.COMMON_TEMPLATE_ATTRIBUTE, local_buffer):
            self._common_template_attribute = objects.TemplateAttribute(tag=enums.Tags.COMMON_TEMPLATE_ATTRIBUTE)
            self._common_template_attribute.read(local_buffer, kmip_version=kmip_version)
    elif self.is_tag_next(enums.Tags.COMMON_ATTRIBUTES, local_buffer):
        attributes = objects.Attributes(tag=enums.Tags.COMMON_ATTRIBUTES)
        attributes.read(local_buffer, kmip_version=kmip_version)
        self._common_template_attribute = objects.convert_attributes_to_template_attribute(attributes)
    if kmip_version < enums.KMIPVersion.KMIP_2_0:
        if self.is_tag_next(enums.Tags.PRIVATE_KEY_TEMPLATE_ATTRIBUTE, local_buffer):
            self._private_key_template_attribute = objects.TemplateAttribute(tag=enums.Tags.PRIVATE_KEY_TEMPLATE_ATTRIBUTE)
            self._private_key_template_attribute.read(local_buffer, kmip_version=kmip_version)
    elif self.is_tag_next(enums.Tags.PRIVATE_KEY_ATTRIBUTES, local_buffer):
        attributes = objects.Attributes(tag=enums.Tags.PRIVATE_KEY_ATTRIBUTES)
        attributes.read(local_buffer, kmip_version=kmip_version)
        self._private_key_template_attribute = objects.convert_attributes_to_template_attribute(attributes)
    if kmip_version < enums.KMIPVersion.KMIP_2_0:
        if self.is_tag_next(enums.Tags.PUBLIC_KEY_TEMPLATE_ATTRIBUTE, local_buffer):
            self._public_key_template_attribute = objects.TemplateAttribute(tag=enums.Tags.PUBLIC_KEY_TEMPLATE_ATTRIBUTE)
            self._public_key_template_attribute.read(local_buffer, kmip_version=kmip_version)
    elif self.is_tag_next(enums.Tags.PUBLIC_KEY_ATTRIBUTES, local_buffer):
        attributes = objects.Attributes(tag=enums.Tags.PUBLIC_KEY_ATTRIBUTES)
        attributes.read(local_buffer, kmip_version=kmip_version)
        self._public_key_template_attribute = objects.convert_attributes_to_template_attribute(attributes)
    self.is_oversized(local_buffer)

def merge(dicto, other):
    if not isinstance(dicto, Dicto):
        dicto = Dicto(dicto)
    if not isinstance(other, Dicto):
        other = Dicto(other)
    for (k, v) in other.__dict__.items():
        if k in dicto and isinstance(dicto[k], Dicto) and isinstance(other[k], Dicto):
            dicto[k] = merge(dicto[k], other[k])
        else:
            dicto[k] = other[k]
    return dicto

def convert(self, txn):
    ofxid = self.mk_ofxid(txn.id)
    metadata = {}
    posting_metadata = {'ofxid': ofxid}
    if isinstance(txn, OfxTransaction):
        posting = Posting(self.name, Amount(txn.amount, self.currency), metadata=posting_metadata)
        return Transaction(date=txn.date, payee=self.format_payee(txn), postings=[posting, posting.clone_inverted(self.mk_dynamic_account(self.format_payee(txn), exclude=self.name))])
    elif isinstance(txn, InvestmentTransaction):
        acct1 = self.name
        acct2 = self.name
        posting1 = None
        posting2 = None
        security = self.maybe_get_ticker(txn.security)
        if isinstance(txn.type, str):
            if re.match('^(buy|sell)', txn.type):
                acct2 = self.unknownaccount or 'Assets:Unknown'
            elif txn.type == 'transfer':
                acct2 = 'Transfer'
            elif txn.type == 'reinvest':
                acct2 = 'Income:Interest'
            elif txn.type == 'income' and txn.income_type == 'DIV':
                metadata['dividend_from'] = security
                acct2 = 'Income:Dividends'
                posting1 = Posting(acct1, Amount(txn.total, self.currency), metadata=posting_metadata)
                posting2 = posting1.clone_inverted(acct2)
            else:
                pass
        elif txn.type in [0, 1, 3, 4]:
            acct2 = self.unknownaccount or 'Assets:Unknown'
        elif txn.type == 2:
            acct2 = 'Income:Interest'
        else:
            pass
        aux_date = None
        if txn.settleDate is not None and txn.settleDate != txn.tradeDate:
            aux_date = txn.settleDate
        if posting1 is None and posting2 is None:
            posting1 = Posting(acct1, Amount(txn.units, security, unlimited=True), unit_price=Amount(txn.unit_price, self.currency, unlimited=True), metadata=posting_metadata)
            posting2 = Posting(acct2, Amount(txn.units * txn.unit_price, self.currency, reverse=True))
        else:
            pass
        return Transaction(date=txn.tradeDate, aux_date=aux_date, payee=self.format_payee(txn), metadata=metadata, postings=[posting1, posting2])

def safe_lower_utf8(x):
    if x is None:
        return None
    x = x.lower()
    if isinstance(x, unicode):
        return x.encode('utf-8')
    return x

def query(self, search_model: QueryModel):
    query_parsed = query_parser(search_model.query)
    self.logger.debug(f'elasticsearch::query::{query_parsed[0]}')
    if search_model.sort is not None:
        self._mapping_to_sort(search_model.sort.keys())
        sort = self._sort_object(search_model.sort)
    else:
        sort = [{'_id': 'asc'}]
    if search_model.query == {}:
        query = {'match_all': {}}
    else:
        query = query_parsed[0]
    body = {'query': query, 'sort': sort, 'from': (search_model.page - 1) * search_model.offset, 'size': search_model.offset}
    page = self.driver._es.search(index=self.driver._index, doc_type='_doc', body=body, q=query_parsed[1])
    object_list = []
    for x in page['hits']['hits']:
        object_list.append(x['_source'])
    return object_list

def find_file(obj):
    if hasattr(obj, '__wrapped__'):
        obj = obj.__wrapped__
    fname = None
    try:
        fname = inspect.getabsfile(obj)
    except TypeError:
        if hasattr(obj, '__class__'):
            try:
                fname = inspect.getabsfile(obj.__class__)
            except TypeError:
                pass
    except:
        pass
    return fname

def real(self, nested_scope=None):
    operation = self.children[0].operation()
    lhs = self.children[1].real(nested_scope)
    rhs = self.children[2].real(nested_scope)
    return operation(lhs, rhs)

def _move_el_inside_block(el, tag):
    for child in el:
        if _contains_block_level_tag(child):
            break
    else:
        import sys
        children_tag = etree.Element(tag)
        children_tag.text = el.text
        el.text = None
        children_tag.extend(list(el))
        el[:] = [children_tag]
        return
    for child in list(el):
        if _contains_block_level_tag(child):
            _move_el_inside_block(child, tag)
            if child.tail:
                tail_tag = etree.Element(tag)
                tail_tag.text = child.tail
                child.tail = None
                el.insert(el.index(child) + 1, tail_tag)
        else:
            child_tag = etree.Element(tag)
            el.replace(child, child_tag)
            child_tag.append(child)
    if el.text:
        text_tag = etree.Element(tag)
        text_tag.text = el.text
        el.text = None
        el.insert(0, text_tag)

