    test = (self.has_quorum, self.has_quorum_possible, self.has_noquorum)
    assert 1 == len([x for x in test if x is not None])
    return True

def response(self, payload):
    if self._state == SASLState.SUCCESS_SIMULATE_CHALLENGE:
        if payload != b'':
            self._state = SASLState.FAILURE
            raise SASLFailure(None, 'protocol violation: mechanism did not respond with an empty response to a challenge with final data – this suggests a protocol-violating early success from the server.')
        self._state = SASLState.SUCCESS
        return (SASLState.SUCCESS, None)
    if self._state != SASLState.CHALLENGE:
        raise RuntimeError('no challenge has been made or negotiation failed')
    try:
        (next_state, payload) = (yield from self.interface.respond(payload))
    except SASLFailure:
        self._state = SASLState.FAILURE
        raise
    next_state = SASLState.from_reply(next_state)
    if next_state == SASLState.SUCCESS and payload is not None:
        self._state = SASLState.SUCCESS_SIMULATE_CHALLENGE
        return (SASLState.CHALLENGE, payload)
    self._state = next_state
    return (next_state, payload)

def assert_title(self, title, **kwargs):
    query = TitleQuery(title, **kwargs)

    @self.synchronize(wait=query.wait)
    def assert_title():
        if not query.resolves_for(self):
            raise ExpectationNotMet(query.failure_message)
        return True
    return assert_title()

def draw_glyph_layout(glyph_layout):
    pushed_color = False
    for line in glyph_layout.lines:
        x = line.x
        y = line.y
        for run in line.runs:
            style = run.style
            if style.color is not None:
                if not pushed_color:
                    bacon.push_color()
                    pushed_color = True
                bacon.set_color(*style.color)
            elif pushed_color:
                bacon.pop_color()
                pushed_color = False
            for glyph in run.glyphs:
                if glyph.image:
                    bacon.draw_image(glyph.image, x + glyph.offset_x, y - glyph.offset_y)
                x += glyph.advance
    if pushed_color:
        bacon.pop_color()

def max_partition(table, schema='default', field=None, filter_map=None, metastore_conn_id='metastore_default'):
    from airflow.hooks.hive_hooks import HiveMetastoreHook
    if '.' in table:
        (schema, table) = table.split('.')
    hh = HiveMetastoreHook(metastore_conn_id=metastore_conn_id)
    return hh.max_partition(schema=schema, table_name=table, field=field, filter_map=filter_map)

def decode_state(cls, state, param='user_state'):
    if state and cls.supports_user_state:
        return json.loads(base64.urlsafe_b64decode(unquote(str(state))).decode('utf-8'))[param]
    else:
        return state if param == 'csrf' else ''

def write_socket_output(connection, socket_obj):
    count = connection.has_output
    if count <= 0:
        return count
    data = connection.output_data()
    if not data:
        return Connection.EOS
    while True:
        try:
            count = socket_obj.send(data)
            break
        except socket.timeout as e:
            LOG.debug('Socket timeout exception %s', str(e))
            raise
        except socket.error as e:
            err = e.errno
            if err in [errno.EAGAIN, errno.EWOULDBLOCK, errno.EINTR]:
                return 0
            LOG.debug('Socket error exception %s', str(e))
            raise
        except Exception as e:
            LOG.debug('unknown socket exception %s', str(e))
            raise
    if count > 0:
        connection.output_written(count)
    elif data:
        LOG.debug('Socket closed')
        count = Connection.EOS
        connection.close_output()
        connection.close_input()
    return count

def to_dict(ramons, flatten=False):
    if type(ramons) is not list:
        ramons = [ramons]
    out_ramons = {}
    for r in ramons:
        out_ramons[r.id] = {'id': r.id, 'type': _reverse_ramon_types[type(r)], 'metadata': vars(r)}
    return out_ramons

def expQt(self, t):
    eLambdaT = np.diag(self._exp_lt(t))
    Qs = self.v.dot(eLambdaT.dot(self.v_inv))
    return np.maximum(0, Qs)

def simple_error_handler(exc, *args):
    if isinstance(exc, exceptions.APIException):
        headers = {}
        if getattr(exc, 'auth_header', None):
            headers['WWW-Authenticate'] = exc.auth_header
        if getattr(exc, 'wait', None):
            headers['X-Throttle-Wait-Seconds'] = '%d' % exc.wait
        return Response({'error': exc.detail}, status=exc.status_code, headers=headers)
    elif isinstance(exc, Http404):
        return Response({'error': 'Not found'}, status=status.HTTP_404_NOT_FOUND)
    elif isinstance(exc, PermissionDenied):
        return Response({'error': 'Permission denied'}, status=status.HTTP_403_FORBIDDEN)
    return None

def mk_constant(cnst_syc):
    s_dt = one(cnst_syc).S_DT[1500]()
    cnst_lsc = one(cnst_syc).CNST_LFSC[1502].CNST_LSC[1503]()
    if s_dt.Name == 'boolean':
        return cnst_lsc.Value.lower() == 'true'
    if s_dt.Name == 'integer':
        return int(cnst_lsc.Value)
    if s_dt.Name == 'real':
        return float(cnst_lsc.Value)
    if s_dt.Name == 'string':
        return str(cnst_lsc.Value)

def add_alt(self, alternatives, alt) -> bool:
    if not hasattr(alternatives, 'parser_tree'):
        if hasattr(alt, 'parser_tree'):
            alternatives.parser_tree = alt.parser_tree
        else:
            alternatives.parser_tree = alt
    else:
        oldnode = alternatives
        if isinstance(oldnode.parser_tree, parsing.Alt):
            oldpt = list(oldnode.parser_tree.ptlist)
        else:
            oldpt = [oldnode.parser_tree]
        oldpt.append(alt.parser_tree)
        alternatives.parser_tree = parsing.Alt(*tuple(oldpt))
    return True

def parse_line(self, line):
    if line[0].isspace():
        new_part = ' ' + line.lstrip()
        self._as_list[self._last_key][-1] += new_part
        dict.__setitem__(self, self._last_key, self[self._last_key] + new_part)
    else:
        (name, value) = line.split(':', 1)
        self.add(name, value.strip())

