def extract_run_id(key):
    filename = key.split('/')[-2]
    run_id = filename.lstrip('run=')
    try:
        datetime.strptime(run_id, '%Y-%m-%d-%H-%M-%S')
        return key
    except ValueError:
        return None

def run_exec(statement, debug_opts=None, start_opts=None, globals_=None, locals_=None):
    dbg = Mdebugger.Trepan(opts=debug_opts)
    try:
        return dbg.run_exec(statement, start_opts=start_opts, globals_=globals_, locals_=locals_)
    except:
        Mpost_mortem.uncaught_exception(dbg)
        pass
    return

def remote_app(self, name, version=None, **kwargs):
    if version is None:
        if 'request_token_url' in kwargs:
            version = '1'
        else:
            version = '2'
    if version == '1':
        remote_app = OAuth1Application(name, clients=cached_clients)
    elif version == '2':
        remote_app = OAuth2Application(name, clients=cached_clients)
    else:
        raise ValueError('unkonwn version %r' % version)
    return self.add_remote_app(remote_app, **kwargs)

def port_to_tcp(port=None):
    domain_name = socket.getfqdn()
    try:
        addr_list = socket.getaddrinfo(domain_name, None)
    except Exception:
        addr_list = socket.getaddrinfo('127.0.0.1', None)
    (family, socktype, proto, canonname, sockaddr) = addr_list[0]
    host = convert_ipv6(sockaddr[0])
    address = 'tcp://' + host
    if port is None:
        port = ()
    if not isinstance(port, int):
        context = zmq.Context()
        try:
            socket_ = context.socket(zmq.REP)
            socket_.ipv6 = is_ipv6(address)
            port = socket_.bind_to_random_port(address, *port)
        except Exception:
            print('Could not connect to {} using {}'.format(address, addr_list))
            pypet_root_logger = logging.getLogger('pypet')
            pypet_root_logger.exception('Could not connect to {}'.format(address))
            raise
        socket_.close()
        context.term()
    return address + ':' + str(port)

