def make_clean_visible(_html, tag_replacement_char=' '):

    def non_tag_chars(html):
        n = 0
        while n < len(html):
            angle = html.find('<', n)
            if angle == -1:
                yield html[n:]
                n = len(html)
                break
            yield html[n:angle]
            n = angle
            while n < len(html):
                nl = html.find('\n', n)
                angle = html.find('>', n)
                if angle == -1:
                    yield (' ' * (len(html) - n))
                    n = len(html)
                    break
                elif nl == -1 or angle < nl:
                    yield (' ' * (angle + 1 - n))
                    n = angle + 1
                    break
                else:
                    yield (' ' * (nl - n) + '\n')
                    n = nl + 1
    if not isinstance(_html, unicode):
        _html = unicode(_html, 'utf-8')
    _html = fix_emails(_html)
    non_tag = ''.join(non_tag_chars(_html))
    return non_tag.encode('utf-8')

