def mixedSuites(self, tests):
    if not tests:
        return []
    head = tests.pop(0)
    if not tests:
        return [head]
    suite = head
    tail = tests[:]
    context = getattr(head, 'context', None)
    if context is not None:
        ancestors = [context] + [a for a in self.ancestry(context)]
        for ancestor in ancestors:
            common = [suite]
            remain = []
            for test in tail:
                found_common = False
                test_ctx = getattr(test, 'context', None)
                if test_ctx is None:
                    remain.append(test)
                    continue
                if test_ctx is ancestor:
                    common.append(test)
                    continue
                for test_ancestor in self.ancestry(test_ctx):
                    if test_ancestor is ancestor:
                        common.append(test)
                        found_common = True
                        break
                if not found_common:
                    remain.append(test)
            if common:
                suite = self.makeSuite(common, ancestor)
            tail = self.mixedSuites(remain)
    return [suite] + tail

