def fit(self, Z):
    self._reset()
    X = Z[:, 'X'] if isinstance(Z, DictRDD) else Z
    check_rdd(X, (np.ndarray, sp.spmatrix))

    def mapper(X):
        X = check_array(X, ('csr', 'csc'), dtype=np.float64)
        if hasattr(X, 'toarray'):
            (mean, var) = mean_variance_axis(X, axis=0)
        else:
            (mean, var) = (np.mean(X, axis=0), np.var(X, axis=0))
        return (X.shape[0], mean, var)

    def reducer(a, b):
        (n_a, mean_a, var_a) = a
        (n_b, mean_b, var_b) = b
        n_ab = n_a + n_b
        mean_ab = (mean_a * n_a + mean_b * n_b) / n_ab
        var_ab = (n_a * var_a + n_b * var_b) / n_ab + n_a * n_b * ((mean_b - mean_a) / n_ab) ** 2
        return (n_ab, mean_ab, var_ab)
    if check_rdd_dtype(X, sp.spmatrix):
        if self.with_mean:
            raise ValueError('Cannot center sparse matrices: pass `with_mean=False` instead. See docstring for motivation and alternatives.')
    (self.n_samples_seen_, self.mean_, self.var_) = X.map(mapper).treeReduce(reducer)
    if self.with_std:
        self.scale_ = _handle_zeros_in_scale(np.sqrt(self.var_))
    else:
        self.scale_ = None
    return self

