def _kl_brute_force(a, b, name=None):

    def squared_frobenius_norm(x):
        return tf.reduce_sum(input_tensor=tf.square(x), axis=[-2, -1])

    def is_diagonal(x):
        return isinstance(x, tf.linalg.LinearOperatorIdentity) or isinstance(x, tf.linalg.LinearOperatorScaledIdentity) or isinstance(x, tf.linalg.LinearOperatorDiag)
    with tf.name_scope(name or 'kl_mvn'):
        if is_diagonal(a.scale) and is_diagonal(b.scale):
            b_inv_a = (a.stddev() / b.stddev())[..., tf.newaxis]
        else:
            b_inv_a = b.scale.solve(a.scale.to_dense())
        kl_div = b.scale.log_abs_determinant() - a.scale.log_abs_determinant() + 0.5 * (-tf.cast(a.scale.domain_dimension_tensor(), a.dtype) + squared_frobenius_norm(b_inv_a) + squared_frobenius_norm(b.scale.solve((b.mean() - a.mean())[..., tf.newaxis])))
        tensorshape_util.set_shape(kl_div, tf.broadcast_static_shape(a.batch_shape, b.batch_shape))
        return kl_div

