    on_fail = opts.get('on_fail')
    throws = opts.get('throws')

    def decorator(f):

        @wraps(f)
        def allower(*args, **kwargs):
            result = allows.run(requirements, identity=identity, on_fail=on_fail, throws=throws, f_args=args, f_kwargs=kwargs)
