def _check_chained_comparison(self, node):
    if node.op != 'and' or len(node.values) < 2:
        return

    def _find_lower_upper_bounds(comparison_node, uses):
        left_operand = comparison_node.left
        for (operator, right_operand) in comparison_node.ops:
            for operand in (left_operand, right_operand):
                value = None
                if isinstance(operand, astroid.Name):
                    value = operand.name
                elif isinstance(operand, astroid.Const):
                    value = operand.value
                if value is None:
                    continue
                if operator in ('<', '<='):
                    if operand is left_operand:
                        uses[value]['lower_bound'].add(comparison_node)
                    elif operand is right_operand:
                        uses[value]['upper_bound'].add(comparison_node)
                elif operator in ('>', '>='):
                    if operand is left_operand:
                        uses[value]['upper_bound'].add(comparison_node)
                    elif operand is right_operand:
                        uses[value]['lower_bound'].add(comparison_node)
            left_operand = right_operand
    uses = collections.defaultdict(lambda : {'lower_bound': set(), 'upper_bound': set()})
    for comparison_node in node.values:
        if isinstance(comparison_node, astroid.Compare):
            _find_lower_upper_bounds(comparison_node, uses)
    for (_, bounds) in uses.items():
        num_shared = len(bounds['lower_bound'].intersection(bounds['upper_bound']))
        num_lower_bounds = len(bounds['lower_bound'])
        num_upper_bounds = len(bounds['upper_bound'])
        if num_shared < num_lower_bounds and num_shared < num_upper_bounds:
            self.add_message('chained-comparison', node=node)
            break

def autorange(self, analyte='total_counts', gwin=5, swin=3, win=20, on_mult=[1.0, 1.5], off_mult=[1.5, 1], transform='log', ploterrs=True, focus_stage='despiked'):
    if focus_stage == 'despiked':
        if 'despiked' not in self.stages_complete:
            focus_stage = 'rawdata'
    if analyte is None:
        analyte = self.internal_standard
    elif analyte in self.analytes:
        self.minimal_analytes.update([analyte])
    fails = {}
    with self.pbar.set(total=len(self.data), desc='AutoRange') as prog:
        for (s, d) in self.data.items():
            f = d.autorange(analyte=analyte, gwin=gwin, swin=swin, win=win, on_mult=on_mult, off_mult=off_mult, ploterrs=ploterrs, transform=transform)
            if f is not None:
                fails[s] = f
            prog.update()
    if len(fails) > 0:
        wstr = '\n\n' + '*' * 41 + '\n' + '                 WARNING\n' + '*' * 41 + '\n' + 'Autorange failed for some samples:\n'
        kwidth = max([len(k) for k in fails.keys()]) + 1
        fstr = '  {:' + '{}'.format(kwidth) + 's}: '
        for k in sorted(fails.keys()):
            wstr += fstr.format(k) + ', '.join(['{:.1f}'.format(f) for f in fails[k][-1]]) + '\n'
        wstr += '\n*** THIS IS NOT NECESSARILY A PROBLEM ***\n' + 'But please check the plots below to make\n' + 'sure they look OK. Failures are marked by\n' + 'dashed vertical red lines.\n\n' + 'To examine an autorange failure in more\n' + 'detail, use the `autorange_plot` method\n' + 'of the failing data object, e.g.:\n' + "dat.data['Sample'].autorange_plot(params)\n" + '*' * 41 + '\n'
        warnings.warn(wstr)
    self.stages_complete.update(['autorange'])
    return

