def run_command(cmd, sudo=False):
    if sudo is True:
        cmd = ['sudo'] + cmd
    try:
        output = Popen(cmd, stderr=STDOUT, stdout=PIPE)
    except FileNotFoundError:
        cmd.pop(0)
        output = Popen(cmd, stderr=STDOUT, stdout=PIPE)
    t = (output.communicate()[0], output.returncode)
    output = {'message': t[0], 'return_code': t[1]}
    if isinstance(output['message'], bytes):
        output['message'] = output['message'].decode('utf-8')
    return output

def get_object_ids(model, meteor_ids):
    if model is ObjectMapping:
        raise TypeError("Can't map ObjectMapping instances through self.")
    meta = model._meta
    alea_unique_fields = [field for field in meta.local_fields if isinstance(field, AleaIdField) and field.unique and (not field.null)]
    result = collections.OrderedDict(((str(meteor_id), None) for meteor_id in meteor_ids))
    if len(alea_unique_fields) == 1:
        aid = alea_unique_fields[0].name
        query = model.objects.filter(**{'%s__in' % aid: meteor_ids}).values_list(aid, 'pk')
    else:
        content_type = ContentType.objects.get_for_model(model)
        query = ObjectMapping.objects.filter(content_type=content_type, meteor_id__in=meteor_ids).values_list('meteor_id', 'object_id')
    for (meteor_id, object_id) in query:
        result[meteor_id] = object_id
    return result

def find_files(directory, ext=None, recurse=True, case_sensitive=False, limit=None, offset=0):
    if ext is None:
        ext = ['aac', 'au', 'flac', 'm4a', 'mp3', 'ogg', 'wav']
    elif isinstance(ext, six.string_types):
        ext = [ext]
    ext = set(ext)
    if not case_sensitive:
        ext = set([e.lower() for e in ext])
        ext |= set([e.upper() for e in ext])
    files = set()
    if recurse:
        for walk in os.walk(directory):
            files |= __get_files(walk[0], ext)
    else:
        files = __get_files(directory, ext)
    files = list(files)
    files.sort()
    files = files[offset:]
    if limit is not None:
        files = files[:limit]
    return files

