def assemble_schedules(schedules, qobj_id=None, qobj_header=None, run_config=None):
    qobj_config = QasmQobjConfig()
    if run_config:
        qobj_config = QasmQobjConfig(**run_config.to_dict())
    instruction_converter = PulseQobjConverter
    instruction_converter = instruction_converter(PulseQobjInstruction, **run_config.to_dict())
    lo_converter = LoConfigConverter(PulseQobjExperimentConfig, run_config.qubit_lo_freq, run_config.meas_lo_freq, **run_config.to_dict())
    qobj_schedules = []
    user_pulselib = set()
    for (idx, schedule) in enumerate(schedules):
        qobj_instructions = []
        for (shift, instruction) in schedule.instructions:
            qobj_instructions.append(instruction_converter(shift, instruction))
            if isinstance(instruction, PulseInstruction):
                user_pulselib.add(instruction.command)
        qobj_experiment_header = QobjExperimentHeader(name=schedule.name or 'Experiment-%d' % idx)
        qobj_schedules.append({'header': qobj_experiment_header, 'instructions': qobj_instructions})
    run_config.pulse_library = [QobjPulseLibrary(name=pulse.name, samples=pulse.samples) for pulse in user_pulselib]
    experiments = []
    if len(run_config.schedule_los) == 1:
        lo_dict = run_config.schedule_los.pop()
        q_los = lo_converter.get_qubit_los(lo_dict)
        if q_los:
            run_config.qubit_lo_freq = q_los
        m_los = lo_converter.get_meas_los(lo_dict)
        if m_los:
            run_config.meas_lo_freq = m_los
    if run_config.schedule_los:
        if len(qobj_schedules) == 1:
            for lo_dict in run_config.schedule_los:
                experiments.append(PulseQobjExperiment(instructions=qobj_schedules[0]['instructions'], experimentheader=qobj_schedules[0]['header'], experimentconfig=lo_converter(lo_dict)))
        elif len(qobj_schedules) == len(run_config.schedule_los):
            for (lo_dict, schedule) in zip(run_config.schedule_los, qobj_schedules):
                experiments.append(PulseQobjExperiment(instructions=schedule['instructions'], experimentheader=schedule['header'], experimentconfig=lo_converter(lo_dict)))
        else:
            raise QiskitError('Invalid LO setting is specified. The LO should be configured for each schedule, or single setup for all schedules (unique), or multiple setups for a single schedule (frequency sweep),or no LO configured at all.')
    else:
        for schedule in qobj_schedules:
            experiments.append(PulseQobjExperiment(instructions=schedule['instructions'], experimentheader=schedule['header']))
    qobj_config = PulseQobjConfig(**run_config.to_dict())
    return PulseQobj(qobj_id=qobj_id, config=qobj_config, experiments=experiments, header=qobj_header)

