def frobenius_norm(self):
    if scipy.sparse.issparse(self.data):
        err = self.data - self.U * self.S * self.V
        err = err.multiply(err)
        err = np.sqrt(err.sum())
    else:
        err = self.data[:, :] - np.dot(np.dot(self.U, self.S), self.V)
        err = np.sqrt(np.sum(err ** 2))
    return err

