def validate_full_path(cls, full_path, **kwargs):
    _client = kwargs.pop('client', None) or cls._client or client
    full_path = full_path.strip()
    if not full_path:
        raise Exception('Vault path "{0}" is invalid. Path must be in the format: "domain:vault:/path" or "vault:/path".'.format(full_path))
    match = cls.VAULT_PATH_RE.match(full_path)
    if not match:
        raise Exception('Vault path "{0}" is invalid. Path must be in the format: "domain:vault:/path" or "vault:/path".'.format(full_path))
    path_parts = match.groupdict()
    if path_parts.get('vault') == '~':
        path_parts = dict(domain=None, vault=None)
    if None in path_parts.values():
        user = _client.get('/v1/user', {})
        defaults = {'domain': user['account']['domain'], 'vault': 'user-{0}'.format(user['id'])}
        path_parts = dict(((k, v or defaults.get(k)) for (k, v) in path_parts.items()))
    full_path = '{domain}:{vault}'.format(**path_parts)
    path_parts['vault_full_path'] = full_path
    return (full_path, path_parts)

def set_class_weight(self, class_weight='auto', y=None):
    if class_weight is None:
        cw = None
        try:
            self.clf.set_params(class_weight=cw)
        except ValueError:
            pass
    elif class_weight == 'auto':
        c = np.bincount(y)
        ii = np.nonzero(c)[0]
        c = c / float(c.sum())
        cw = dict(zip(ii[::-1], c[ii]))
        try:
            self.clf.set_params(class_weight=cw)
        except ValueError:
            import warnings
            warnings.warn("Tried to set class_weight, but failed. The classifier probably doesn't support it")

def abort_request(self, stream, ident, parent):
    msg_ids = parent['content'].get('msg_ids', None)
    if isinstance(msg_ids, basestring):
        msg_ids = [msg_ids]
    if not msg_ids:
        self.abort_queues()
    for mid in msg_ids:
        self.aborted.add(str(mid))
    content = dict(status='ok')
    reply_msg = self.session.send(stream, 'abort_reply', content=content, parent=parent, ident=ident)
    self.log.debug('%s', reply_msg)

