def save(self, filename=None, v1=1, v2_version=4, v23_sep='/'):
    framedata = self._prepare_framedata(v2_version, v23_sep)
    framesize = len(framedata)
    if not framedata:
        try:
            self.delete(filename)
        except EnvironmentError as err:
            from errno import ENOENT
            if err.errno != ENOENT:
                raise
        return
    if filename is None:
        filename = self.filename
    try:
        f = open(filename, 'rb+')
    except IOError as err:
        from errno import ENOENT
        if err.errno != ENOENT:
            raise
        f = open(filename, 'ab')
        f = open(filename, 'rb+')
    try:
        idata = f.read(10)
        header = self._prepare_id3_header(idata, framesize, v2_version)
        (header, outsize, insize) = header
        data = header + framedata + b'\x00' * (outsize - framesize)
        if insize < outsize:
            insert_bytes(f, outsize - insize, insize + 10)
        f.seek(0)
        f.write(data)
        try:
            f.seek(-128, 2)
        except IOError as err:
            from errno import EINVAL
            if err.errno != EINVAL:
                raise
            f.seek(0, 2)
        data = f.read(128)
        try:
            idx = data.index(b'TAG')
        except ValueError:
            offset = 0
            has_v1 = False
        else:
            offset = idx - len(data)
            has_v1 = True
        f.seek(offset, 2)
        if v1 == 1 and has_v1 or v1 == 2:
            f.write(MakeID3v1(self))
        else:
            f.truncate()
    finally:
        f.close()

def absfile(path, where=None):
    orig = path
    if where is None:
        where = os.getcwd()
    if isinstance(where, list) or isinstance(where, tuple):
        for maybe_path in where:
            maybe_abs = absfile(path, maybe_path)
            if maybe_abs is not None:
                return maybe_abs
        return None
    if not os.path.isabs(path):
        path = os.path.normpath(os.path.abspath(os.path.join(where, path)))
    if path is None or not os.path.exists(path):
        if where != os.getcwd():
            path = os.path.normpath(os.path.abspath(os.path.join(os.getcwd(), orig)))
    if path is None or not os.path.exists(path):
        return None
    if os.path.isdir(path):
        init = os.path.join(path, '__init__.py')
        if os.path.isfile(init):
            return init
    elif os.path.isfile(path):
        return path
    return None

