def log_ndtr(x, series_order=3, name='log_ndtr'):
    if not isinstance(series_order, int):
        raise TypeError('series_order must be a Python integer.')
    if series_order < 0:
        raise ValueError('series_order must be non-negative.')
    if series_order > 30:
        raise ValueError('series_order must be <= 30.')
    with tf.name_scope(name):
        x = tf.convert_to_tensor(value=x, name='x')
        if dtype_util.base_equal(x.dtype, tf.float64):
            lower_segment = LOGNDTR_FLOAT64_LOWER
            upper_segment = LOGNDTR_FLOAT64_UPPER
        elif dtype_util.base_equal(x.dtype, tf.float32):
            lower_segment = LOGNDTR_FLOAT32_LOWER
            upper_segment = LOGNDTR_FLOAT32_UPPER
        else:
            raise TypeError('x.dtype=%s is not supported.' % x.dtype)
        return tf.where(tf.greater(x, upper_segment), -_ndtr(-x), tf.where(tf.greater(x, lower_segment), tf.math.log(_ndtr(tf.maximum(x, lower_segment))), _log_ndtr_lower(tf.minimum(x, lower_segment), series_order)))

def poll(self):
    start_time = time.time()
    for agent in self.agents:
        for collect in agent.reader:
            if not collect:
                return 0
            for chunk in collect:
                (ts, prepared_results) = chunk
                if self.load_start_time and int(ts) >= self.load_start_time:
                    ready_to_send = {'timestamp': int(ts), 'data': {self.hash_hostname(agent.host): {'comment': agent.config.comment, 'metrics': prepared_results}}}
                    self.__collected_data.append(ready_to_send)
    logger.debug('Polling/decoding agents data took: %.2fms', (time.time() - start_time) * 1000)
    collected_data_length = len(self.__collected_data)
    if not self.first_data_received and self.__collected_data:
        self.first_data_received = True
        logger.info('Monitoring received first data.')
    else:
        self.send_collected_data()
    return collected_data_length

