def run(script='TEMP3D_default.mlx', log=None, ml_log=None, mlp_in=None, mlp_out=None, overwrite=False, file_in=None, file_out=None, output_mask=None, cmd=None, ml_version=ML_VERSION, print_meshlabserver_output=True):
    if cmd is None:
        cmd = 'meshlabserver'
        if ml_log is not None:
            ml_log_file = open(ml_log, 'w')
            ml_log_file.close()
            cmd += ' -l %s' % ml_log
        if mlp_in is not None:
            mlp_in = util.make_list(mlp_in)
            for val in mlp_in:
                cmd += ' -p "%s"' % val
        if mlp_out is not None:
            cmd += ' -w %s' % mlp_out
            if overwrite:
                cmd += ' -v'
        if mlp_in is None and file_in is None:
            file_in = ['TEMP3D.xyz']
        if file_in is not None:
            file_in = util.make_list(file_in)
            for val in file_in:
                if val == 'bunny':
                    cmd += ' -i "%s"' % os.path.join(THIS_MODULEPATH, os.pardir, 'models', 'bunny_flat(1Z).ply')
                elif val == 'bunny_raw':
                    cmd += ' -i "%s"' % os.path.join(THIS_MODULEPATH, os.pardir, 'models', 'bunny_raw(-1250Y).ply')
                else:
                    cmd += ' -i "%s"' % val
        if file_out is not None:
            file_out = util.make_list(file_out)
            if output_mask is not None:
                output_mask = util.make_list(output_mask)
            else:
                output_mask = []
            for (index, val) in enumerate(file_out):
                cmd += ' -o "%s"' % val
                try:
                    cmd += ' %s' % output_mask[index]
                except IndexError:
                    cmd += ' %s' % default_output_mask(val, ml_version=ml_version)
        if script is not None:
            cmd += ' -s "%s"' % script
    if log is not None:
        log_file = open(log, 'a')
        log_file.write('meshlabserver cmd = %s\n' % cmd)
        log_file.write('***START OF MESHLAB STDOUT & STDERR***\n')
        log_file.close()
        log_file = open(log, 'a')
    elif print_meshlabserver_output:
        log_file = None
        print('meshlabserver cmd = %s' % cmd)
        print('***START OF MESHLAB STDOUT & STDERR***')
    else:
        log_file = open(os.devnull, 'w')
    while True:
        return_code = subprocess.call(cmd, shell=True, stdout=log_file, stderr=log_file, universal_newlines=True)
        if log is not None:
            log_file.close()
        if return_code == 0 or handle_error(program_name='MeshLab', cmd=cmd, log=log):
            break
    if log is not None:
        log_file = open(log, 'a')
        log_file.write('***END OF MESHLAB STDOUT & STDERR***\n')
        log_file.write('meshlabserver return code = %s\n\n' % return_code)
        log_file.close()
    return return_code

