def translate_name(name):
    parts = name.split('_')
    i = 0
    while parts[i] == '':
        parts[i] = '_'
        i += 1
    parts[i] = parts[i].lower()
    for j in range(i + 1, len(parts)):
        parts[j] = parts[j].capitalize()
    i = len(parts) - 1
    while parts[i] == '':
        parts[i] = '_'
        i -= 1
    return ''.join(parts)

def find_bp(self, filename, lineno, frame):
    possibles = self.bplist[filename, lineno]
    for i in range(0, len(possibles)):
        b = possibles[i]
        if not b.enabled:
            continue
        if not checkfuncname(b, frame):
            continue
        b.hits += 1
        if not b.condition:
            if b.ignore > 0:
                b.ignore = b.ignore - 1
                continue
            else:
                return (b, True)
        else:
            try:
                val = eval(b.condition, frame.f_globals, frame.f_locals)
                if val:
                    if b.ignore > 0:
                        b.ignore = b.ignore - 1
                    else:
                        return (b, True)
            except:
                return (b, False)
            pass
        pass
    return (None, None)

def set_attributes(self, **kwargs):
    self.clear_derived()
    kwargs = dict(kwargs)
    for (name, value) in kwargs.items():
        try:
            self.getp(name)
        except KeyError:
            print('Warning: %s does not have attribute %s' % (type(self), name))
        try:
            self.setp(name, clear_derived=False, **value)
        except TypeError:
            try:
                self.setp(name, *value, clear_derived=False)
            except (TypeError, KeyError):
                try:
                    self.setp(name, clear_derived=False, value=value)
                except (TypeError, KeyError):
                    self.__setattr__(name, value)
        self._missing.pop(name, None)
    if self._missing:
        raise ValueError('One or more required properties are missing ', self._missing.keys())

