def eval(self, orig):
    _le = {}
    _err = []
    for (k, v) in self.sup_items():
        if k in DoNotCompare:
            continue
        if k in orig:
            if is_lesser(orig[k], v):
                _le[k] = orig[k]
            else:
                _err.append({'claim': k, 'policy': orig[k], 'err': v, 'signer': self.iss})
        else:
            _le[k] = v
    for (k, v) in orig.items():
        if k in DoNotCompare:
            continue
        if k not in _le:
            _le[k] = v
    self.le = _le
    self.err = _err

