def set_sgr_code(self, params):
    if not params:
        return
    code = params.pop(0)
    if code == 0:
        self.reset_sgr()
    elif code == 1:
        if self.bold_text_enabled:
            self.bold = True
        else:
            self.intensity = 1
    elif code == 2:
        self.intensity = 0
    elif code == 3:
        self.italic = True
    elif code == 4:
        self.underline = True
    elif code == 22:
        self.intensity = 0
        self.bold = False
    elif code == 23:
        self.italic = False
    elif code == 24:
        self.underline = False
    elif code >= 30 and code <= 37:
        self.foreground_color = code - 30
    elif code == 38 and params and (params.pop(0) == 5):
        if params:
            self.foreground_color = params.pop(0)
    elif code == 39:
        self.foreground_color = None
    elif code >= 40 and code <= 47:
        self.background_color = code - 40
    elif code == 48 and params and (params.pop(0) == 5):
        if params:
            self.background_color = params.pop(0)
    elif code == 49:
        self.background_color = None
    self.set_sgr_code(params)

