def __truncate(self, line_arr, max_width):

    def is_space(chunk):
        return all([True if i == ' ' else False for i in chunk])

    def is_empty(chunks, markups):
        result = []
        for chunk in chunks:
            if chunk in markups:
                result.append(True)
            elif is_space(chunk):
                result.append(True)
            else:
                result.append(False)
        return all(result)
    left = max_width
    result = ''
    markups = self.markup.get_markup_vars()
    for (num, chunk) in enumerate(line_arr):
        if chunk in markups:
            result += chunk
        elif left > 0:
            if len(chunk) <= left:
                result += chunk
                left -= len(chunk)
            else:
                leftover = (chunk[left:],) + line_arr[num + 1:]
                was_cut = not is_empty(leftover, markups)
                if was_cut:
                    result += chunk[:left - 1] + self.markup.RESET + u'…'
                else:
                    result += chunk[:left]
                left = 0
    return result

def filter_by_date(df, date_col: str, date_format: str='%Y-%m-%d', start: str=None, stop: str=None, atdate: str=None):
    mask = None
    if start is None and stop is None and (atdate is None):
        raise TypeError('either "start", "stop" or "atdate" must be specified')
    if start is not None and atdate is not None:
        raise TypeError('"start" and "atdate" are mutually exclusive')
    if stop is not None and atdate is not None:
        raise TypeError('"stop" and "atdate" are mutually exclusive')
    filtercol = str(uuid4())
    df[filtercol] = pd.to_datetime(df[date_col], format=date_format)
    if atdate is not None:
        mask = df[filtercol] == parse_date(atdate, date_format)
    elif start is not None and stop is not None:
        mask = (df[filtercol] >= parse_date(start, date_format)) & (df[filtercol] < parse_date(stop, date_format))
    elif stop is None:
        mask = df[filtercol] >= parse_date(start, date_format)
    elif start is None:
        mask = df[filtercol] < parse_date(stop, date_format)
    return df[mask].drop(filtercol, axis=1)

def _append_instruction(self, obj, qargs=None):
    if isinstance(obj, Instruction):
        mat = None
        if hasattr(obj, 'to_matrix'):
            try:
                mat = obj.to_matrix()
            except QiskitError:
                pass
        if mat is not None:
            op = self.compose(mat, qargs=qargs)
            self._data = op.data
        else:
            if obj.definition is None:
                raise QiskitError('Cannot apply Instruction: {}'.format(obj.name))
            for (instr, qregs, cregs) in obj.definition:
                if cregs:
                    raise QiskitError('Cannot apply instruction with classical registers: {}'.format(instr.name))
                new_qargs = [tup[1] for tup in qregs]
                self._append_instruction(instr, qargs=new_qargs)
    else:
        raise QiskitError('Input is not an instruction.')

