def _feed(self):
    self.plan = StpdReader(self.stpd_filename)
    if self.cached_stpd:
        self.plan = list(self.plan)
    for task in self.plan:
        if self.quit.is_set():
            logger.info('Stop feeding: gonna quit')
            return
        while True:
            try:
                self.task_queue.put(task, timeout=1)
                break
            except Full:
                if self.quit.is_set() or self.workers_finished:
                    return
                else:
                    continue
    workers_count = self.instances
    logger.info('Feeded all data. Publishing %d killer tasks' % workers_count)
    retry_delay = 1
    for _ in range(5):
        try:
            [self.task_queue.put(None, timeout=1) for _ in xrange(0, workers_count)]
            break
        except Full:
            logger.debug("Couldn't post killer tasks because queue is full. Retrying in %ss", retry_delay)
            time.sleep(retry_delay)
            retry_delay *= 2
    try:
        logger.info('Waiting for workers')
        map(lambda x: x.join(), self.pool)
        logger.info('All workers exited.')
        self.workers_finished = True
    except (KeyboardInterrupt, SystemExit):
        self.task_queue.close()
        self.results.close()
        self.quit.set()
        logger.info('Going to quit. Waiting for workers')
        map(lambda x: x.join(), self.pool)
        self.workers_finished = True

def check(self, uuid=None, usage_limits_count=None, cryptographic_usage_mask=None, lease_time=None, credential=None):
    mask = 0
    for m in cryptographic_usage_mask:
        mask |= m.value
    operation = Operation(OperationEnum.CHECK)
    request_payload = payloads.CheckRequestPayload(unique_identifier=uuid, usage_limits_count=usage_limits_count, cryptographic_usage_mask=mask, lease_time=lease_time)
    batch_item = messages.RequestBatchItem(operation=operation, request_payload=request_payload)
    request = self._build_request_message(credential, [batch_item])
    response = self._send_and_receive_message(request)
    batch_item = response.batch_items[0]
    payload = batch_item.response_payload
    result = {}
    if payload:
        result['unique_identifier'] = payload.unique_identifier
    if payload.usage_limits_count is not None:
        result['usage_limits_count'] = payload.usage_limits_count
    if payload.cryptographic_usage_mask is not None:
        masks = []
        for enumeration in enums.CryptographicUsageMask:
            if payload.cryptographic_usage_mask & enumeration.value:
                masks.append(enumeration)
        result['cryptographic_usage_mask'] = masks
    if payload.lease_time is not None:
        result['lease_time'] = payload.lease_time
    result['result_status'] = batch_item.result_status.value
    try:
        result['result_reason'] = batch_item.result_reason.value
    except Exception:
        result['result_reason'] = batch_item.result_reason
    try:
        result['result_message'] = batch_item.result_message.value
    except Exception:
        result['result_message'] = batch_item.result_message
    return result

