def plfit(self, nosmall=True, finite=False, quiet=False, silent=False, usefortran=False, usecy=False, xmin=None, verbose=False, discrete=None, discrete_approx=True, discrete_n_alpha=1000, skip_consistency_check=False):
    x = self.data
    if any(x < 0):
        raise ValueError('Power law distributions are only valid for positive data.  Remove negative values before fitting.')
    z = np.sort(x)
    (xmins, argxmins) = np.unique(z, return_index=True)
    self._nunique = len(xmins)
    if self._nunique == len(x) and discrete is None:
        if verbose:
            print('Using CONTINUOUS fitter because there are no repeated values.')
        discrete = False
    elif self._nunique < len(x) and discrete is None:
        if verbose:
            print('Using DISCRETE fitter because there are repeated values.')
        discrete = True
    t = time.time()
    if xmin is None:
        if discrete:
            self.discrete_best_alpha(approximate=discrete_approx, n_alpha=discrete_n_alpha, verbose=verbose, finite=finite)
            return (self._xmin, self._alpha)
        elif usefortran and fortranOK:
            (kstest_values, alpha_values) = fplfit.plfit(z, 0)
            if not quiet:
                print('FORTRAN plfit executed in %f seconds' % (time.time() - t))
        elif usecy and cyOK:
            (kstest_values, alpha_values) = cplfit.plfit_loop(z, nosmall=False, zunique=xmins, argunique=argxmins)
            if not quiet:
                print('CYTHON plfit executed in %f seconds' % (time.time() - t))
        else:
            f_alpha = alpha_gen(z)
            f_kstest = kstest_gen(z)
            alpha_values = np.asarray(list(map(f_alpha, xmins)), dtype='float')
            kstest_values = np.asarray(list(map(f_kstest, xmins)), dtype='float')
            if not quiet:
                print('PYTHON plfit executed in %f seconds' % (time.time() - t))
        if not quiet:
            if usefortran and (not fortranOK):
                raise ImportError('fortran fplfit did not load')
            if usecy and (not cyOK):
                raise ImportError('cython cplfit did not load')
        sigma = (alpha_values - 1) / np.sqrt(len(z) - argxmins)
        if nosmall:
            goodvals = sigma < 0.1
            nmax = argmin(goodvals)
            if nmax <= 0:
                nmax = len(xmins) - 1
                if not silent:
                    print('Not enough data left after flagging low S/N points.  Using all data.')
        else:
            nmax = len(xmins) - 1
        best_ks_index = argmin(kstest_values[:nmax])
        xmin = xmins[best_ks_index]
        self._alpha_values = alpha_values
        self._xmin_kstest = kstest_values
        if scipyOK:
            self._ks_prob_all = np.array([scipy.stats.ksone.sf(D_stat, len(kstest_values) - ii) for (ii, D_stat) in enumerate(kstest_values)])
        self._sigma = sigma
        n = np.count_nonzero(z >= xmin)
        alpha = 1.0 + float(n) / sum(log(z[z >= xmin] / xmin))
        try:
            if not skip_consistency_check:
                np.testing.assert_almost_equal(alpha, alpha_values[best_ks_index], decimal=4)
        except AssertionError:
            raise AssertionError('The alpha value computed was not self-consistent.  This should not happen.  However, it is possible that this is a numerical uncertainty issue; the values being compared are {0} and {1}.If they are close enough, set skip_consistency_check=True.'.format(alpha, alpha_values[best_ks_index]))
    z = z[z >= xmin]
    n = len(z)
    alpha = 1.0 + float(n) / sum(log(z / xmin))
    if finite:
        alpha = alpha * (n - 1.0) / n + 1.0 / n
    if n < 50 and (not finite) and (not silent):
        print('(PLFIT) Warning: finite-size bias may be present. n=%i' % n)
    ks = max(abs(np.arange(n) / float(n) - (1 - (xmin / z) ** (alpha - 1))))
    L = n * log((alpha - 1) / xmin) - alpha * sum(log(z / xmin))
    self._likelihood = L
    self._xmin = xmin
    self._xmins = xmins
    self._alpha = alpha
    self._alphaerr = (alpha - 1) / np.sqrt(n)
    self._ks = ks
    if scipyOK:
        self._ks_prob = scipy.stats.ksone.sf(ks, n)
    self._ngtx = n
    if n == 1:
        if not silent:
            print('Failure: only 1 point kept.  Probably not a power-law distribution.')
        self._alpha = alpha = 0
        self._alphaerr = 0
        self._likelihood = L = 0
        self._ks = 0
        self._ks_prob = 0
        self._xmin = xmin
        return (xmin, 0)
    if np.isnan(L) or np.isnan(xmin) or np.isnan(alpha):
        raise ValueError('plfit failed; returned a nan')
    if not quiet:
        if verbose:
            print('The lowest value included in the power-law fit, ', end=' ')
        print('xmin: %g' % xmin, end=' ')
        if verbose:
            print('\nThe number of values above xmin, ', end=' ')
        print('n(>xmin): %i' % n, end=' ')
        if verbose:
            print('\nThe derived power-law alpha (p(x)~x^-alpha) with MLE-derived error, ', end=' ')
        print('alpha: %g +/- %g  ' % (alpha, self._alphaerr), end=' ')
        if verbose:
            print('\nThe log of the Likelihood (the maximized parameter; you minimized the negative log likelihood), ', end=' ')
        print('Log-Likelihood: %g  ' % L, end=' ')
        if verbose:
            print('\nThe KS-test statistic between the best-fit power-law and the data, ', end=' ')
        print('ks: %g' % ks, end=' ')
        if scipyOK:
            if verbose:
                print(' occurs with probability  ', end=' ')
            print('p(ks): %g' % self._ks_prob)
        else:
            print()
    return (xmin, alpha)

def xml_to_dict(raw_xml):

    def node_to_dict(node):
        d = {}
        d.update(node.items())
        text = getattr(node, 'text', None)
        if text is not None:
            d['__text__'] = text
        childs = {}
        for child in node:
            childs.setdefault(child.tag, []).append(node_to_dict(child))
        d.update(childs.items())
        return d
    purged_xml = remove_invalid_xml_chars(raw_xml)
    try:
        tree = xml.etree.ElementTree.fromstring(purged_xml)
    except xml.etree.ElementTree.ParseError as e:
        cause = 'XML stream %s' % str(e)
        raise ParseError(cause=cause)
    d = node_to_dict(tree)
    return d

