def invoke_one(self, line):
    funname = line.pop(0)
    context = self.contexts[-1]
    func = self.find_function(context, funname)
    if isinstance(func, dict):
        self.contexts.append(func)
        self._check_initialize_context()
        return (None, line, False)
    if func.takes_cmdline is True:
        val = func(line)
        line = []
    else:
        (posargs, kwargs, line) = self.process_arguments(func, line)
        if inspect.isclass(func) and (not func.metadata.spec_filled(posargs, kwargs)):
            raise ValidationError('Not enough parameters specified to call function', function=func.metadata.name, signature=func.metadata.signature())
        val = func(*posargs, **kwargs)
    finished = True
    if func.finalizer is True:
        self.contexts.pop()
    elif val is not None:
        if func.metadata.returns_data():
            val = func.metadata.format_returnvalue(val)
        else:
            self.contexts.append(val)
            self._check_initialize_context()
            finished = False
            val = None
    return (val, line, finished)

def intersect(self, other):
    if not isinstance(other, self.__class__):
        m = 'You can only intersect striplogs with each other.'
        raise StriplogError(m)
    result = []
    for iv in self:
        for jv in other:
            try:
                result.append(iv.intersect(jv))
            except IntervalError:
                pass
    return Striplog(result)

def get(self, job_id, job_get_options=None, custom_headers=None, raw=False, **operation_config):
    select = None
    if job_get_options is not None:
        select = job_get_options.select
    expand = None
    if job_get_options is not None:
        expand = job_get_options.expand
    timeout = None
    if job_get_options is not None:
        timeout = job_get_options.timeout
    client_request_id = None
    if job_get_options is not None:
        client_request_id = job_get_options.client_request_id
    return_client_request_id = None
    if job_get_options is not None:
        return_client_request_id = job_get_options.return_client_request_id
    ocp_date = None
    if job_get_options is not None:
        ocp_date = job_get_options.ocp_date
    if_match = None
    if job_get_options is not None:
        if_match = job_get_options.if_match
    if_none_match = None
    if job_get_options is not None:
        if_none_match = job_get_options.if_none_match
    if_modified_since = None
    if job_get_options is not None:
        if_modified_since = job_get_options.if_modified_since
    if_unmodified_since = None
    if job_get_options is not None:
        if_unmodified_since = job_get_options.if_unmodified_since
    url = self.get.metadata['url']
    path_format_arguments = {'batchUrl': self._serialize.url('self.config.batch_url', self.config.batch_url, 'str', skip_quote=True), 'jobId': self._serialize.url('job_id', job_id, 'str')}
    url = self._client.format_url(url, **path_format_arguments)
    query_parameters = {}
    query_parameters['api-version'] = self._serialize.query('self.api_version', self.api_version, 'str')
    if select is not None:
        query_parameters['$select'] = self._serialize.query('select', select, 'str')
    if expand is not None:
        query_parameters['$expand'] = self._serialize.query('expand', expand, 'str')
    if timeout is not None:
        query_parameters['timeout'] = self._serialize.query('timeout', timeout, 'int')
    header_parameters = {}
    header_parameters['Accept'] = 'application/json'
    if self.config.generate_client_request_id:
        header_parameters['client-request-id'] = str(uuid.uuid1())
    if custom_headers:
        header_parameters.update(custom_headers)
    if self.config.accept_language is not None:
        header_parameters['accept-language'] = self._serialize.header('self.config.accept_language', self.config.accept_language, 'str')
    if client_request_id is not None:
        header_parameters['client-request-id'] = self._serialize.header('client_request_id', client_request_id, 'str')
    if return_client_request_id is not None:
        header_parameters['return-client-request-id'] = self._serialize.header('return_client_request_id', return_client_request_id, 'bool')
    if ocp_date is not None:
        header_parameters['ocp-date'] = self._serialize.header('ocp_date', ocp_date, 'rfc-1123')
    if if_match is not None:
        header_parameters['If-Match'] = self._serialize.header('if_match', if_match, 'str')
    if if_none_match is not None:
        header_parameters['If-None-Match'] = self._serialize.header('if_none_match', if_none_match, 'str')
    if if_modified_since is not None:
        header_parameters['If-Modified-Since'] = self._serialize.header('if_modified_since', if_modified_since, 'rfc-1123')
    if if_unmodified_since is not None:
        header_parameters['If-Unmodified-Since'] = self._serialize.header('if_unmodified_since', if_unmodified_since, 'rfc-1123')
    request = self._client.get(url, query_parameters, header_parameters)
    response = self._client.send(request, stream=False, **operation_config)
    if response.status_code not in [200]:
        raise models.BatchErrorException(self._deserialize, response)
    deserialized = None
    header_dict = {}
    if response.status_code == 200:
        deserialized = self._deserialize('CloudJob', response)
        header_dict = {'client-request-id': 'str', 'request-id': 'str', 'ETag': 'str', 'Last-Modified': 'rfc-1123'}
    if raw:
        client_raw_response = ClientRawResponse(deserialized, response)
        client_raw_response.add_headers(header_dict)
        return client_raw_response
    return deserialized

def interfaces(node, herited=True, handler_func=_iface_hdlr):
    try:
        implements = bases.Instance(node).getattr('__implements__')[0]
    except exceptions.NotFoundError:
        return
    if not herited and implements.frame() is not node:
        return
    found = set()
    missing = False
    for iface in node_classes.unpack_infer(implements):
        if iface is astroid.Uninferable:
            missing = True
            continue
        if iface not in found and handler_func(iface):
            found.add(iface)
            yield iface
    if missing:
        raise exceptions.InferenceError()

