def _maybe_validate_perm(perm, validate_args, name=None):
    with tf.name_scope(name or 'maybe_validate_perm'):
        assertions = []
        if not dtype_util.is_integer(perm.dtype):
            raise TypeError('`perm` must be integer type')
        msg = '`perm` must be a vector.'
        if tensorshape_util.rank(perm.shape) is not None:
            if tensorshape_util.rank(perm.shape) != 1:
                raise ValueError(msg[:-1] + ', saw rank: {}.'.format(tensorshape_util.rank(perm.shape)))
        elif validate_args:
            assertions += [assert_util.assert_rank(perm, 1, message=msg)]
        perm_ = tf.get_static_value(perm)
        msg = '`perm` must be a valid permutation vector.'
        if perm_ is not None:
            if not np.all(np.arange(np.size(perm_)) == np.sort(perm_)):
                raise ValueError(msg[:-1] + ', saw: {}.'.format(perm_))
        elif validate_args:
            assertions += [assert_util.assert_equal(tf.sort(perm), tf.range(tf.size(input=perm)), message=msg)]
        return assertions

def form_values(self):
    results = []
    for el in self.inputs:
        name = el.name
        if not name:
            continue
        tag = _nons(el.tag)
        if tag == 'textarea':
            results.append((name, el.value))
        elif tag == 'select':
            value = el.value
            if el.multiple:
                for v in value:
                    results.append((name, v))
            elif value is not None:
                results.append((name, el.value))
        else:
            assert tag == 'input', 'Unexpected tag: %r' % el
            if el.checkable and (not el.checked):
                continue
            if el.type in ('submit', 'image', 'reset'):
                continue
            value = el.value
            if value is not None:
                results.append((name, el.value))
    return results

def other_causatives(self, case_obj, variant_obj):
    variant_id = variant_obj['display_name'].rsplit('_', 1)[0]
    institute_causatives = self.get_causatives(variant_obj['institute'])
    for causative_id in institute_causatives:
        other_variant = self.variant(causative_id)
        if not other_variant:
            continue
        not_same_case = other_variant['case_id'] != case_obj['_id']
        same_variant = other_variant['display_name'].startswith(variant_id)
        if not_same_case and same_variant:
            yield other_variant

def _handle_stranded_msgs(self, eid, uuid):
    outstanding = self.queues[eid]
    for msg_id in outstanding:
        self.pending.remove(msg_id)
        self.all_completed.add(msg_id)
        try:
            raise error.EngineError('Engine %r died while running task %r' % (eid, msg_id))
        except:
            content = error.wrap_exception()
        header = {}
        header['engine'] = uuid
        header['date'] = datetime.now()
        rec = dict(result_content=content, result_header=header, result_buffers=[])
        rec['completed'] = header['date']
        rec['engine_uuid'] = uuid
        try:
            self.db.update_record(msg_id, rec)
        except Exception:
            self.log.error('DB Error handling stranded msg %r', msg_id, exc_info=True)

