def formatday(self, day, weekday):
    super(MiniEventCalendar, self).formatday(day, weekday)
    now = get_now()
    self.day = day
    if day == 0:
        return '<td class="noday">&nbsp;</td>'
    elif now.month == self.mo and now.year == self.yr and (day == now.day):
        if day in self.count:
            self.popover_helper()
            return self.wkday_today + self.anch + self.cal_event + self.end
        else:
            return self.wkday_today + self.anch + self.end
    elif day in self.count:
        self.popover_helper()
        return self.wkday_not_today + self.anch + self.cal_event + self.end
    else:
        return self.wkday_not_today + self.anch + self.end

def _has_different_parameters_default_value(original, overridden):
    if original.args is None or overridden.args is None:
        return False
    all_args = chain(original.args, original.kwonlyargs)
    original_param_names = [param.name for param in all_args]
    default_missing = object()
    for param_name in original_param_names:
        try:
            original_default = original.default_value(param_name)
        except astroid.exceptions.NoDefault:
            original_default = default_missing
        try:
            overridden_default = overridden.default_value(param_name)
        except astroid.exceptions.NoDefault:
            overridden_default = default_missing
        default_list = [arg == default_missing for arg in (original_default, overridden_default)]
        if any(default_list) and (not all(default_list)):
            return True
        astroid_type_compared_attr = {astroid.Const: 'value', astroid.ClassDef: 'name', astroid.Tuple: 'elts', astroid.List: 'elts'}
        handled_types = tuple((astroid_type for astroid_type in astroid_type_compared_attr))
        original_type = _get_node_type(original_default, handled_types)
        if original_type:
            if not isinstance(overridden_default, original_type):
                return True
            if not _check_arg_equality(original_default, overridden_default, astroid_type_compared_attr[original_type]):
                return True
    return False

def delete_pool(name, session=None):
    if not (name and name.strip()):
        raise AirflowBadRequest("Pool name shouldn't be empty")
    pool = session.query(Pool).filter_by(pool=name).first()
    if pool is None:
        raise PoolNotFound("Pool '%s' doesn't exist" % name)
    session.delete(pool)
    session.commit()
    return pool

