def configure(self, options, config):
    try:
        self.status.pop('active')
    except KeyError:
        pass
    if not hasattr(options, 'multiprocess_workers'):
        self.enabled = False
        return
    if config.worker:
        return
    self.config = config
    try:
        workers = int(options.multiprocess_workers)
    except (TypeError, ValueError):
        workers = 0
    if workers:
        _import_mp()
        if Process is None:
            self.enabled = False
            return
        self.enabled = True
