def __find_incongruities(self, op, index):
    if len(self) == 1:
        return
    hits = []
    intervals = []
    if self.order == 'depth':
        (one, two) = ('base', 'top')
    else:
        (one, two) = ('top', 'base')
    for (i, iv) in enumerate(self[:-1]):
        next_iv = self[i + 1]
        if op(getattr(iv, one), getattr(next_iv, two)):
            hits.append(i)
            top = getattr(iv, one)
            base = getattr(next_iv, two)
            iv_gap = Interval(top, base)
            intervals.append(iv_gap)
    if index and hits:
        return hits
    elif intervals:
        return Striplog(intervals)
    else:
        return

def _get_functions(expr, ldelim='(', rdelim=')'):
    tpars = _pair_delims(expr, ldelim=ldelim, rdelim=rdelim)
    alphas = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
    fchars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'
    tfuncs = []
    for (lnum, rnum) in tpars:
        if lnum and expr[lnum - 1] in fchars:
            for (cnum, char) in enumerate(reversed(expr[:lnum])):
                if char not in fchars:
                    break
            else:
                cnum = lnum
            tfuncs.append({'fname': expr[lnum - cnum:lnum], 'expr': expr[lnum + 1:rnum], 'start': lnum - cnum, 'stop': rnum})
            if expr[lnum - cnum] not in alphas:
                raise RuntimeError('Function name `{0}` is not valid'.format(expr[lnum - cnum:lnum]))
    return tfuncs

