        if not isinstance(addy, MultisigAddress):
            raise with_context(exc=TypeError('Incorrect input type for {cls} (expected {expected}, actual {actual}).'.format(actual=type(addy).__name__, cls=type(self).__name__, expected=MultisigAddress.__name__)), context={'actual_input': addy})
        security_level = addy.security_level
        if security_level < 1:
            raise with_context(exc=ValueError('Unable to determine security level for {type} (is ``digests`` populated correctly?).'.format(type=type(addy).__name__)), context={'actual_input': addy, 'security_level': security_level})
        if not addy.balance:
            raise with_context(exc=ValueError('Cannot add input with empty/unknown balance to {type} (use ``Iota.get_balances`` to get balance first).'.format(type=type(self).__name__)), context={'actual_input': addy})
        self._create_input_transactions(addy)
