def _add_discount(self, product, quantity, discounts):

    def matches(discount):
        if isinstance(discount.clause, conditions.DiscountForCategory):
            return discount.clause.category == product.category
        else:
            return discount.clause.product == product

    def value(discount):
        if discount.clause.percentage is not None:
            return discount.clause.percentage * product.price
        else:
            return discount.clause.price
    discounts = [i for i in discounts if matches(i)]
    discounts.sort(key=value)
    for candidate in reversed(discounts):
        if quantity == 0:
            break
        elif candidate.quantity == 0:
            continue
        discount_item = commerce.DiscountItem.objects.create(product=product, cart=self.cart, discount=candidate.discount, quantity=quantity)
        ours = discount_item.quantity
        allowed = candidate.quantity
        if ours > allowed:
            discount_item.quantity = allowed
            discount_item.save()
            quantity = ours - allowed
        else:
            quantity = 0
        candidate.quantity -= discount_item.quantity

def __resolve_bare_symbol(ctx: ParserContext, form: sym.Symbol) -> Union[MaybeClass, VarRef]:
    assert form.ns is None
    v = ctx.current_ns.find(form)
    if v is not None:
        return VarRef(form=form, var=v, env=ctx.get_node_env())
    if '.' in form.name:
        raise ParserException("symbol names may not contain the '.' operator", form=form)
    munged = munge(form.name, allow_builtins=True)
    if munged in vars(builtins):
        return MaybeClass(form=form, class_=munged, target=vars(builtins)[munged], env=ctx.get_node_env())
    assert munged not in vars(ctx.current_ns.module)
    raise ParserException(f"unable to resolve symbol '{form}' in this context", form=form)

