def exec_command(self, domain, function, operator, value=None):
    if operator in CMDS[domain][function]['supported_operators']:
        if operator is '=' and value is None:
            raise ValueError('No value provided')
        if value is None:
            cmd = ''.join([CMDS[domain][function]['cmd'], operator])
        else:
            cmd = ''.join([CMDS[domain][function]['cmd'], operator, str(value)])
    else:
        raise ValueError('Invalid operator provided %s' % operator)
    if self._open_connection():
        self.telnet.write(''.join(['\r', cmd, '\n']).encode())
        loop = 3
        while loop:
            msg = self.telnet.read_until('\n'.encode(), self.timeout)
            if msg == '':
                loop -= 1
                continue
            msg = msg.decode().strip('\r\n')
            if msg.strip().split('=')[0].lower() == '.'.join([domain, function]).lower():
                return msg.strip().split('=')[1]
        raise RuntimeError('Failed to read response')
    raise RuntimeError('Failed to open connection')

def f_find_idx(self, name_list, predicate):
    if self._is_run and (not self.v_full_copy):
        raise TypeError('You cannot use this function during a multiprocessing signle run and not having ``v_full_copy=True``.')
    if isinstance(name_list, str):
        name_list = [name_list]
    iter_list = []
    for name in name_list:
        param = self.f_get(name)
        if not param.v_is_parameter:
            raise TypeError('`%s` is not a parameter it is a %s, find idx is not applicable' % (name, str(type(param))))
        if param.f_has_range():
            iter_list.append(iter(param.f_get_range(copy=False)))
        else:
            iter_list.append(itools.repeat(param.f_get(), len(self)))
    logic_iter = map(predicate, *iter_list)
    for (idx, item) in enumerate(logic_iter):
        if item:
            yield idx

def execute_work(self, key, command):
    if key is None:
        return
    self.log.info('%s running %s', self.__class__.__name__, command)
    try:
        subprocess.check_call(command, close_fds=True)
        state = State.SUCCESS
    except subprocess.CalledProcessError as e:
        state = State.FAILED
        self.log.error('Failed to execute task %s.', str(e))
    self.result_queue.put((key, state))

def shift_annotations(self, time):
    total_re = []
    total_sq = []
    for (name, tier) in self.tiers.items():
        squashed = []
        for (aid, (begin, end, value, _)) in tier[0].items():
            if self.timeslots[end] + time <= 0:
                squashed.append((name, aid))
            elif self.timeslots[begin] + time < 0:
                total_sq.append((name, self.timeslots[begin], self.timeslots[end], value))
                self.timeslots[begin] = 0
            else:
                self.timeslots[begin] += time
                self.timeslots[end] += time
        for (name, aid) in squashed:
            (start, end, value, _) = self.tiers[name][0][aid]
            del self.tiers[name][0][aid]
            del self.annotations[aid]
            total_re.append((name, self.timeslots[start], self.timeslots[end], value))
    return (total_sq, total_re)

