def pprint_vector(vector, limit=False, width=None, indent=0, eng=False, frac_length=3):
    num_digits = 12
    approx = lambda x: float(x) if '.' not in x else round(float(x), num_digits)

    def limstr(value):
        str1 = str(value)
        iscomplex = isinstance(value, complex)
        str1 = str1.lstrip('(').rstrip(')')
        if '.' not in str1:
            return str1
        if iscomplex:
            sign = '+' if value.imag >= 0 else '-'
            regexp = re.compile('(.*(?:[Ee][\\+-]\\d+)?)' + ('\\+' if sign == '+' else '-') + '(.*(?:[Ee][\\+-]\\d+)?j)')
            (rvalue, ivalue) = regexp.match(str1).groups()
            return str(complex(approx(rvalue), approx(sign + ivalue.strip('j')))).lstrip('(').rstrip(')')
        str2 = str(round(value, num_digits))
        return str2 if len(str1) > len(str2) else str1

    def _str(*args):
        ret = [(limstr(element) if not eng else peng(element, frac_length, True)) if not isinstance(element, complex) else limstr(element) if not eng else '{real}{sign}{imag}j'.format(real=peng(element.real, frac_length, True), imag=peng(abs(element.imag), frac_length, True), sign='+' if element.imag >= 0 else '-') for element in args]
        return ret[0] if len(ret) == 1 else ret
    if vector is None:
        return 'None'
    lvector = len(vector)
    if not limit or (limit and lvector < 7):
        items = _str(*vector)
        uret = '[ {0} ]'.format(', '.join(items))
    else:
        items = _str(*vector[:3] + vector[-3:])
        uret = '[ {0}, ..., {1} ]'.format(', '.join(items[:3]), ', '.join(items[-3:]))
    if width is None or len(uret) < width:
        return uret
    if any([len(item) > width - 4 for item in items]):
        raise ValueError('Argument `width` is too small')
    wobj = textwrap.TextWrapper(initial_indent='[ ', width=width)
    rlist = wobj.wrap(uret[2:])
    first_line = rlist[0]
    first_line_elements = first_line.count(',')
    uret_left = ','.join(uret.split(',')[first_line_elements:]).replace('...,', '')
    wobj = textwrap.TextWrapper(width=width - 2)
    wrapped_text = wobj.wrap(uret_left.lstrip())
    rlist = [first_line] + [' ' * (indent + 2) + item.rstrip() for item in wrapped_text]
    last_line = rlist[-1]
    last_line_elements = last_line.count(',') + 1
    if limit and lvector > 6:
        if first_line_elements < 3 or (first_line_elements == 3 and last_line_elements < 3):
            rlist = ['[ {0},'.format(_str(vector[0])), _str(vector[1]), _str(vector[2]), '...', _str(vector[-3]), _str(vector[-2]), '{0} ]'.format(_str(vector[-1]))]
            first_line_elements = 1
        else:
            rlist = ['[ {0},'.format(', '.join(_str(*vector[:3]))), '...', '{0} ]'.format(', '.join(_str(*vector[-3:])))]
        first_line = rlist[0]
    elif limit:
        rlist = [item.lstrip() for item in rlist]
    first_comma_index = first_line.find(',')
    actual_width = len(first_line) - 2
    if not eng:
        if not limit:
            return '\n'.join(rlist)
        num_elements = len(rlist)
        return '\n'.join(['{spaces}{line}{comma}'.format(spaces=' ' * (indent + 2) if num > 0 else '', line=line.center(actual_width).rstrip() if line.strip() == '...' else line, comma=',' if num < num_elements - 1 and (not line.endswith(',')) and (line.strip() != '...') else '') if num > 0 else line for (num, line) in enumerate(rlist)])
    if limit:
        remainder_list = [line.lstrip() for line in rlist[1:]]
    else:
        remainder_list = _split_every(text=uret[len(first_line):], sep=',', count=first_line_elements, lstrip=True)
    new_wrapped_lines_list = [first_line]
    for line in remainder_list[:-1]:
        new_wrapped_lines_list.append('{0},'.format(line).rjust(actual_width) if line != '...' else line.center(actual_width).rstrip())
    if remainder_list[-1].find(',') == -1:
        marker = len(remainder_list[-1]) - 2
    else:
        marker = remainder_list[-1].find(',')
    new_wrapped_lines_list.append('{0}{1}'.format((first_comma_index - marker - 2) * ' ', remainder_list[-1]))
    return '\n'.join(['{spaces}{line}'.format(spaces=' ' * (indent + 2), line=line) if num > 0 else line for (num, line) in enumerate(new_wrapped_lines_list)])

def findsource(object):
    file = getsourcefile(object) or getfile(object)
    globals_dict = None
    if inspect.isframe(object):
        globals_dict = object.f_globals
    else:
        module = getmodule(object, file)
        if module:
            globals_dict = module.__dict__
    lines = linecache.getlines(file, globals_dict)
    if not lines:
        raise IOError('could not get source code')
    if ismodule(object):
        return (lines, 0)
    if isclass(object):
        name = object.__name__
        pat = re.compile('^(\\s*)class\\s*' + name + '\\b')
        candidates = []
        for i in range(len(lines)):
            match = pat.match(lines[i])
            if match:
                if lines[i][0] == 'c':
                    return (lines, i)
                candidates.append((match.group(1), i))
        if candidates:
            candidates.sort()
            return (lines, candidates[0][1])
        else:
            raise IOError('could not find class definition')
    if ismethod(object):
        object = object.im_func
    if isfunction(object):
        object = object.func_code
    if istraceback(object):
        object = object.tb_frame
    if isframe(object):
        object = object.f_code
    if iscode(object):
        if not hasattr(object, 'co_firstlineno'):
            raise IOError('could not find function definition')
        pat = re.compile('^(\\s*def\\s)|(.*(?<!\\w)lambda(:|\\s))|^(\\s*@)')
        pmatch = pat.match
        lnum = min(object.co_firstlineno, len(lines)) - 1
        while lnum > 0:
            if pmatch(lines[lnum]):
                break
            lnum -= 1
        return (lines, lnum)
    raise IOError('could not find code object')

