def scan_module(egg_dir, base, name, stubs):
    filename = os.path.join(base, name)
    if filename[:-1] in stubs:
        return True
    pkg = base[len(egg_dir) + 1:].replace(os.sep, '.')
    module = pkg + (pkg and '.' or '') + os.path.splitext(name)[0]
    if sys.version_info < (3, 3):
        skip = 8
    else:
        skip = 12
    f = open(filename, 'rb')
    f.read(skip)
    code = marshal.load(f)
    f.close()
    safe = True
    symbols = dict.fromkeys(iter_symbols(code))
    for bad in ['__file__', '__path__']:
        if bad in symbols:
            log.warn('%s: module references %s', module, bad)
            safe = False
    if 'inspect' in symbols:
        for bad in ['getsource', 'getabsfile', 'getsourcefile', 'getfilegetsourcelines', 'findsource', 'getcomments', 'getframeinfo', 'getinnerframes', 'getouterframes', 'stack', 'trace']:
            if bad in symbols:
                log.warn('%s: module MAY be using inspect.%s', module, bad)
                safe = False
    if '__name__' in symbols and '__main__' in symbols and ('.' not in module):
        if sys.version[:3] == '2.4':
            log.warn("%s: top-level module may be 'python -m' script", module)
            safe = False
    return safe

def get_cluster_health_using_policy(self, nodes_health_state_filter=0, applications_health_state_filter=0, events_health_state_filter=0, exclude_health_statistics=False, include_system_application_health_statistics=False, timeout=60, application_health_policy_map=None, cluster_health_policy=None, custom_headers=None, raw=False, **operation_config):
