def try_run(obj, names):
    for name in names:
        func = getattr(obj, name, None)
        if func is not None:
            if type(obj) == types.ModuleType:
                try:
                    (args, varargs, varkw, defaults) = inspect.getargspec(func)
                except TypeError:
                    if hasattr(func, '__call__'):
                        func = func.__call__
                    try:
                        (args, varargs, varkw, defaults) = inspect.getargspec(func)
                        args.pop(0)
                    except TypeError:
                        raise TypeError('Attribute %s of %r is not a python function. Only functions or callables may be used as fixtures.' % (name, obj))
                if len(args):
                    log.debug('call fixture %s.%s(%s)', obj, name, obj)
                    return func(obj)
            log.debug('call fixture %s.%s', obj, name)
            return func()

def shutdown(self, *args):
    try:
        self._shutdown()
        if self.process:
            self.process.wait()
            self.process.stdout.close()
            self.process.stdin.close()
            self.process.stderr.close()
        self.finished = True
        self.send_testcase('', '127.0.0.1', self.config.ports['servers']['TCASE_PORT'])
        self.logger.debug('[{0}] - PJFProcessMonitor successfully completed'.format(time.strftime('%H:%M:%S')))
    except Exception as e:
        raise PJFBaseException(e.message if hasattr(e, 'message') else str(e))

def _select_best_remaining_qubit(self, prog_qubit):
    reliab_store = {}
    for hw_qubit in self.available_hw_qubits:
        reliab = 1
        for n in self.prog_graph.neighbors(prog_qubit):
            if n in self.prog2hw:
                reliab *= self.swap_costs[self.prog2hw[n]][hw_qubit]
        reliab *= self.readout_errors[hw_qubit]
        reliab_store[hw_qubit] = reliab
    max_reliab = 0
    best_hw_qubit = None
    for hw_qubit in reliab_store:
        if reliab_store[hw_qubit] > max_reliab:
            max_reliab = reliab_store[hw_qubit]
            best_hw_qubit = hw_qubit
    return best_hw_qubit

