def run_query(self, sql, destination_dataset_table=None, write_disposition='WRITE_EMPTY', allow_large_results=False, flatten_results=None, udf_config=None, use_legacy_sql=None, maximum_billing_tier=None, maximum_bytes_billed=None, create_disposition='CREATE_IF_NEEDED', query_params=None, labels=None, schema_update_options=(), priority='INTERACTIVE', time_partitioning=None, api_resource_configs=None, cluster_fields=None, location=None):
    if time_partitioning is None:
        time_partitioning = {}
    if location:
        self.location = location
    if not api_resource_configs:
        api_resource_configs = self.api_resource_configs
    else:
        _validate_value('api_resource_configs', api_resource_configs, dict)
    configuration = deepcopy(api_resource_configs)
    if 'query' not in configuration:
        configuration['query'] = {}
    else:
        _validate_value("api_resource_configs['query']", configuration['query'], dict)
    if sql is None and (not configuration['query'].get('query', None)):
        raise TypeError('`BigQueryBaseCursor.run_query` missing 1 required positional argument: `sql`')
    allowed_schema_update_options = ['ALLOW_FIELD_ADDITION', 'ALLOW_FIELD_RELAXATION']
    if not set(allowed_schema_update_options).issuperset(set(schema_update_options)):
        raise ValueError('{0} contains invalid schema update options. Please only use one or more of the following options: {1}'.format(schema_update_options, allowed_schema_update_options))
    if schema_update_options:
        if write_disposition not in ['WRITE_APPEND', 'WRITE_TRUNCATE']:
            raise ValueError("schema_update_options is only allowed if write_disposition is 'WRITE_APPEND' or 'WRITE_TRUNCATE'.")
    if destination_dataset_table:
        (destination_project, destination_dataset, destination_table) = _split_tablename(table_input=destination_dataset_table, default_project_id=self.project_id)
        destination_dataset_table = {'projectId': destination_project, 'datasetId': destination_dataset, 'tableId': destination_table}
    if cluster_fields:
        cluster_fields = {'fields': cluster_fields}
    query_param_list = [(sql, 'query', None, six.string_types), (priority, 'priority', 'INTERACTIVE', six.string_types), (use_legacy_sql, 'useLegacySql', self.use_legacy_sql, bool), (query_params, 'queryParameters', None, list), (udf_config, 'userDefinedFunctionResources', None, list), (maximum_billing_tier, 'maximumBillingTier', None, int), (maximum_bytes_billed, 'maximumBytesBilled', None, float), (time_partitioning, 'timePartitioning', {}, dict), (schema_update_options, 'schemaUpdateOptions', None, tuple), (destination_dataset_table, 'destinationTable', None, dict), (cluster_fields, 'clustering', None, dict)]
    for param_tuple in query_param_list:
        (param, param_name, param_default, param_type) = param_tuple
        if param_name not in configuration['query'] and param in [None, {}, ()]:
            if param_name == 'timePartitioning':
                param_default = _cleanse_time_partitioning(destination_dataset_table, time_partitioning)
            param = param_default
        if param not in [None, {}, ()]:
            _api_resource_configs_duplication_check(param_name, param, configuration['query'])
            configuration['query'][param_name] = param
            _validate_value(param_name, configuration['query'][param_name], param_type)
            if param_name == 'schemaUpdateOptions' and param:
                self.log.info("Adding experimental 'schemaUpdateOptions': %s", schema_update_options)
            if param_name == 'destinationTable':
                for key in ['projectId', 'datasetId', 'tableId']:
                    if key not in configuration['query']['destinationTable']:
                        raise ValueError("Not correct 'destinationTable' in api_resource_configs. 'destinationTable' must be a dict with {'projectId':'', 'datasetId':'', 'tableId':''}")
                configuration['query'].update({'allowLargeResults': allow_large_results, 'flattenResults': flatten_results, 'writeDisposition': write_disposition, 'createDisposition': create_disposition})
    if 'useLegacySql' in configuration['query'] and configuration['query']['useLegacySql'] and ('queryParameters' in configuration['query']):
        raise ValueError('Query parameters are not allowed when using legacy SQL')
    if labels:
        _api_resource_configs_duplication_check('labels', labels, configuration)
        configuration['labels'] = labels
    return self.run_with_configuration(configuration)

