def decompress_G2(p: G2Compressed) -> G2Uncompressed:
    (z1, z2) = p
    b_flag1 = z1 % POW_2_383 // POW_2_382
    if b_flag1 == 1:
        return Z2
    x1 = z1 % POW_2_381
    x2 = z2
    x = FQ2([x2, x1])
    y = modular_squareroot_in_FQ2(x ** 3 + b2)
    if y is None:
        raise ValueError('Failed to find a modular squareroot')
    a_flag1 = z1 % POW_2_382 // POW_2_381
    (y_re, y_im) = y.coeffs
    if y_im > 0 and y_im * 2 // q != a_flag1 or (y_im == 0 and y_re * 2 // q != a_flag1):
        y = FQ2((y * -1).coeffs)
    if not is_on_curve((x, y, FQ2([1, 0])), b2):
        raise ValueError('The given point is not on the twisted curve over FQ**2')
    return (x, y, FQ2([1, 0]))

def fit(self, x, y=None, batch_size=32, nb_epoch=10, validation_data=None, distributed=True):
    if distributed:
        if isinstance(x, np.ndarray) and isinstance(y, np.ndarray):
            training_data = to_sample_rdd(x, y)
            if validation_data:
                validation_data = to_sample_rdd(*validation_data)
        elif (isinstance(x, RDD) or isinstance(x, DataSet)) and (not y):
            training_data = x
        else:
            raise TypeError('Unsupported training data type: %s' % type(x))
        callBigDlFunc(self.bigdl_type, 'fit', self.value, training_data, batch_size, nb_epoch, validation_data)
    else:
        if validation_data:
            val_x = [JTensor.from_ndarray(x) for x in to_list(validation_data[0])]
            val_y = JTensor.from_ndarray(validation_data[1])
        else:
            (val_x, val_y) = (None, None)
        callBigDlFunc(self.bigdl_type, 'fit', self.value, [JTensor.from_ndarray(x) for x in to_list(x)], JTensor.from_ndarray(y), batch_size, nb_epoch, val_x, val_y, multiprocessing.cpu_count())

