def _handle_successful_job(self, job):
    result = job.result
    task_id = job.kwargs['task_id']
    try:
        task = self.registry.get(task_id)
    except NotFoundError:
        logger.warning('Task %s not found; related job #%s will not be rescheduled', task_id, job.id)
        return
    if task.archiving_cfg and task.archiving_cfg.fetch_from_archive:
        logger.info('Job #%s (task: %s) successfully finished', job.id, task_id)
        return
    if result.nitems > 0:
        task.backend_args['next_from_date'] = unixtime_to_datetime(result.max_date)
        if result.offset:
            task.backend_args['next_offset'] = result.offset
    job_args = self._build_job_arguments(task)
    delay = task.scheduling_cfg.delay if task.scheduling_cfg else WAIT_FOR_QUEUING
    job_id = self._scheduler.schedule_job_task(Q_UPDATING_JOBS, task_id, job_args, delay=delay)
    logger.info('Job #%s (task: %s, old job: %s) re-scheduled', job_id, task_id, job.id)

def date_range(start_date, end_date=None, num=None, delta=None):
    if not delta:
        return []
    if end_date and start_date > end_date:
        raise Exception('Wait. start_date needs to be before end_date')
    if end_date and num:
        raise Exception('Wait. Either specify end_date OR num')
    if not end_date and (not num):
        end_date = timezone.utcnow()
    delta_iscron = False
    tz = start_date.tzinfo
    if isinstance(delta, six.string_types):
        delta_iscron = True
        start_date = timezone.make_naive(start_date, tz)
        cron = croniter(delta, start_date)
    elif isinstance(delta, timedelta):
        delta = abs(delta)
    dates = []
    if end_date:
        if timezone.is_naive(start_date):
            end_date = timezone.make_naive(end_date, tz)
        while start_date <= end_date:
            if timezone.is_naive(start_date):
                dates.append(timezone.make_aware(start_date, tz))
            else:
                dates.append(start_date)
            if delta_iscron:
                start_date = cron.get_next(datetime)
            else:
                start_date += delta
    else:
        for _ in range(abs(num)):
            if timezone.is_naive(start_date):
                dates.append(timezone.make_aware(start_date, tz))
            else:
                dates.append(start_date)
            if delta_iscron:
                if num > 0:
                    start_date = cron.get_next(datetime)
                else:
                    start_date = cron.get_prev(datetime)
            elif num > 0:
                start_date += delta
            else:
                start_date -= delta
    return sorted(dates)

def _seq_pprinter_factory(start, end, basetype):

    def inner(obj, p, cycle):
        typ = type(obj)
        if basetype is not None and typ is not basetype and (typ.__repr__ != basetype.__repr__):
            return p.text(typ.__repr__(obj))
        if cycle:
            return p.text(start + '...' + end)
        step = len(start)
        p.begin_group(step, start)
        for (idx, x) in enumerate(obj):
            if idx:
                p.text(',')
                p.breakable()
            p.pretty(x)
        if len(obj) == 1 and type(obj) is tuple:
            p.text(',')
        p.end_group(step, end)
    return inner

