            title = self.window().windowTitle()
            cancel = QtGui.QMessageBox.Cancel
            okay = QtGui.QMessageBox.Ok
            if closing_widget._may_close:
                msg = 'You are closing the tab : ' + '"' + self.tab_widget.tabText(current_tab) + '"'
                info = 'Would you like to quit the Kernel and close all attached Consoles as well?'
                justthis = QtGui.QPushButton('&No, just this Tab', self)
                justthis.setShortcut('N')
                closeall = QtGui.QPushButton('&Yes, close all', self)
                closeall.setShortcut('Y')
                closeall.setShortcut('Ctrl+D')
                box = QtGui.QMessageBox(QtGui.QMessageBox.Question, title, msg)
                box.setInformativeText(info)
                box.addButton(cancel)
                box.addButton(justthis, QtGui.QMessageBox.NoRole)
                box.addButton(closeall, QtGui.QMessageBox.YesRole)
                box.setDefaultButton(closeall)
                box.setEscapeButton(cancel)
                pixmap = QtGui.QPixmap(self._app.icon.pixmap(QtCore.QSize(64, 64)))
                box.setIconPixmap(pixmap)
                reply = box.exec_()
                if reply == 1:
                    for slave in slave_tabs:
                        background(slave.kernel_manager.stop_channels)
                        self.tab_widget.removeTab(self.tab_widget.indexOf(slave))
                    closing_widget.execute('exit')
                    self.tab_widget.removeTab(current_tab)
                    background(kernel_manager.stop_channels)
                elif reply == 0:
                    if not closing_widget._existing:
                        closing_widget.execute('exit True')
                    self.tab_widget.removeTab(current_tab)
                    background(kernel_manager.stop_channels)
            else:
                reply = QtGui.QMessageBox.question(self, title, 'Are you sure you want to close this Console?' + '\nThe Kernel and other Consoles will remain active.', okay | cancel, defaultButton=okay)
                if reply == okay:
                    self.tab_widget.removeTab(current_tab)
    elif keepkernel:
        self.tab_widget.removeTab(current_tab)
        background(kernel_manager.stop_channels)
    else:
        self.tab_widget.removeTab(current_tab)
        if kernel_manager and kernel_manager.channels_running:
            for slave in slave_tabs:
                background(slave.kernel_manager.stop_channels)
                self.tab_widget.removeTab(self.tab_widget.indexOf(slave))
            kernel_manager.shutdown_kernel()
            background(kernel_manager.stop_channels)
    self.update_tab_bar_visibility()

def _get_concatenation(extractors, text, *, ignore_whitespace=True):
    (ignored_ws, use_text) = _split_ignored(text, ignore_whitespace)
    (extractor, *remaining) = extractors
    child = _call_extractor(extractor, use_text)
    child.add_ignored(ignored_ws)
    node = ParseNode(ParseNodeType.concatenation, children=[child])
    if remaining:
        return node.merged(_get_concatenation(remaining, text[child.consumed:], ignore_whitespace=ignore_whitespace))
    else:
        return node

