def diag_jacobian(xs, ys=None, sample_shape=None, fn=None, parallel_iterations=10, name=None):
    with tf.compat.v1.name_scope(name, 'jacobians_diag', [xs, ys]):
        if sample_shape is None:
            sample_shape = [1]
        jacobians_diag_res = []
        xs = list(xs) if _is_list_like(xs) else [xs]
        xs = [tf.convert_to_tensor(value=x) for x in xs]
        if not tf.executing_eagerly():
            if ys is None:
                if fn is None:
                    raise ValueError('Both `ys` and `fn` can not be `None`')
                else:
                    ys = fn(*xs)
            ys = list(ys) if _is_list_like(ys) else [ys]
            if len(xs) != len(ys):
                raise ValueError('`xs` and `ys` should have the same length')
            for (y, x) in zip(ys, xs):
                y_ = y + tf.zeros_like(x)
                y_ = tf.reshape(y, tf.concat([sample_shape, [-1]], -1))
                n = tf.size(input=x) / tf.cast(tf.reduce_prod(input_tensor=sample_shape), dtype=tf.int32)
                n = tf.cast(n, dtype=tf.int32)
                loop_vars = [0, tf.TensorArray(x.dtype, n)]

                def loop_body(j):
                    res = tf.gradients(ys=y_[..., j], xs=x)[0]
                    if res is None:
                        res = tf.zeros(tf.concat([sample_shape, [1]], -1), dtype=x.dtype)
                    else:
                        res = tf.reshape(res, tf.concat([sample_shape, [-1]], -1))
                        res = tf.expand_dims(res, 0)
                        res = res[..., j]
                    return res
                (_, jacobian_diag_res) = tf.while_loop(cond=lambda j, _: j < n, body=lambda j, result: (j + 1, result.write(j, loop_body(j))), loop_vars=loop_vars, parallel_iterations=parallel_iterations)
                shape_x = tf.shape(input=x)
                reshaped_jacobian_diag = tf.transpose(a=jacobian_diag_res.stack())
                reshaped_jacobian_diag = tf.reshape(reshaped_jacobian_diag, shape_x)
                jacobians_diag_res.append(reshaped_jacobian_diag)
        else:
            if fn is None:
                raise ValueError('`fn` can not be `None` when eager execution is enabled')
            if ys is None:
                ys = fn(*xs)

            def fn_slice(i, j):

                def fn_broadcast(*state):
                    res = fn(*state)
                    res = list(res) if _is_list_like(res) else [res]
                    if len(res) != len(state):
                        res *= len(state)
                    res = [tf.reshape(r + tf.zeros_like(s), tf.concat([sample_shape, [-1]], -1)) for (r, s) in zip(res, state)]
                    return res
                return lambda *state: tf.expand_dims(fn_broadcast(*state)[i], 0)[..., j]

            def make_loop_body(i, x):

                def _fn(j, result):
                    res = value_and_gradient(fn_slice(i, j), xs)[1][i]
                    if res is None:
                        res = tf.zeros(tf.concat([sample_shape, [1]], -1), dtype=x.dtype)
                    else:
                        res = tf.reshape(res, tf.concat([sample_shape, [-1]], -1))
                        res = res[..., j]
                    return (j + 1, result.write(j, res))
                return _fn
            for (i, x) in enumerate(xs):
                n = tf.size(input=x) / tf.cast(tf.reduce_prod(input_tensor=sample_shape), dtype=tf.int32)
                n = tf.cast(n, dtype=tf.int32)
                loop_vars = [0, tf.TensorArray(x.dtype, n)]
                (_, jacobian_diag_res) = tf.while_loop(cond=lambda j, _: j < n, body=make_loop_body(i, x), loop_vars=loop_vars, parallel_iterations=parallel_iterations)
                shape_x = tf.shape(input=x)
                reshaped_jacobian_diag = tf.transpose(a=jacobian_diag_res.stack())
                reshaped_jacobian_diag = tf.reshape(reshaped_jacobian_diag, shape_x)
                jacobians_diag_res.append(reshaped_jacobian_diag)
    return (ys, jacobians_diag_res)

def count(self):
    filters = self._filters
    if self._order_by:
        filters += (self._order_by.lstrip('-'),)
    if not filters:
        size = _connect(self._model).hlen(self._model._namespace + '::')
        limit = self._limit or (0, 2 ** 64)
        size = max(size - max(limit[0], 0), 0)
        return min(size, limit[1])
    return self._model._gindex.count(_connect(self._model), filters)

