def insert_rows(self, table, rows, target_fields=None, commit_every=1000):
    if target_fields:
        target_fields = ', '.join(target_fields)
        target_fields = '({})'.format(target_fields)
    else:
        target_fields = ''
    conn = self.get_conn()
    cur = conn.cursor()
    if self.supports_autocommit:
        cur.execute('SET autocommit = 0')
    conn.commit()
    i = 0
    for row in rows:
        i += 1
        lst = []
        for cell in row:
            if isinstance(cell, basestring):
                lst.append("'" + str(cell).replace("'", "''") + "'")
            elif cell is None:
                lst.append('NULL')
            elif type(cell) == float and numpy.isnan(cell):
                lst.append('NULL')
            elif isinstance(cell, numpy.datetime64):
                lst.append("'" + str(cell) + "'")
            elif isinstance(cell, datetime):
                lst.append("to_date('" + cell.strftime('%Y-%m-%d %H:%M:%S') + "','YYYY-MM-DD HH24:MI:SS')")
            else:
                lst.append(str(cell))
        values = tuple(lst)
        sql = 'INSERT /*+ APPEND */ INTO {0} {1} VALUES ({2})'.format(table, target_fields, ','.join(values))
        cur.execute(sql)
        if i % commit_every == 0:
            conn.commit()
            self.log.info('Loaded %s into %s rows so far', i, table)
    conn.commit()
    cur.close()
    conn.close()
    self.log.info('Done loading. Loaded a total of %s rows', i)

