def start(self, n):
    dlist = []
    for (host, n) in self.engines.iteritems():
        if isinstance(n, (tuple, list)):
            (n, args) = n
        else:
            args = copy.deepcopy(self.engine_args)
        if '@' in host:
            (user, host) = host.split('@', 1)
        else:
            user = None
        for i in range(n):
            if i > 0:
                time.sleep(self.delay)
            el = self.launcher_class(work_dir=self.work_dir, config=self.config, log=self.log, profile_dir=self.profile_dir, cluster_id=self.cluster_id)
            if i > 0:
                el.to_send = []
            el.engine_cmd = self.engine_cmd
            el.engine_args = args
            el.on_stop(self._notice_engine_stopped)
            d = el.start(user=user, hostname=host)
            self.launchers['%s/%i' % (host, i)] = el
            dlist.append(d)
    self.notify_start(dlist)
    return dlist

