def transpose(self, *axes):
    new = argpack(axes)
    old = range(self.ndim)
    istransposeable(new, old)
    if new == old:
        return self._barray

    def f(v):
        return v.transpose(new)
    newrdd = self._barray._rdd.mapValues(f)
    newshape = self._barray.keys.shape + tuple((self.shape[i] for i in new))
    return BoltArraySpark(newrdd, shape=newshape).__finalize__(self._barray)

def normal(x, layer_fn=tf.compat.v1.layers.dense, loc_fn=lambda x: x, scale_fn=1.0, name=None):
    with tf.compat.v1.name_scope(name, 'normal', [x]):
        x = tf.convert_to_tensor(value=x, name='x')
        if callable(scale_fn):
            y = layer_fn(x, 2)
            loc = loc_fn(y[..., 0])
            scale = scale_fn(y[..., 1])
        else:
            y = tf.squeeze(layer_fn(x, 1), axis=-1)
            loc = loc_fn(y)
            scale = tf.cast(scale_fn, loc.dtype.base_dtype)
        return tfd.Normal(loc=loc, scale=scale)

