def validate_ppoi(value, return_converted_tuple=False):
    valid_ppoi = True
    to_return = None
    if isinstance(value, tuple):
        valid_ppoi = validate_ppoi_tuple(value)
        if valid_ppoi:
            to_return = value
    else:
        tup = tuple()
        try:
            string_split = [float(segment.strip()) for segment in value.split('x') if float(segment.strip()) >= 0 and float(segment.strip()) <= 1]
