def get_results(self, client_id, msg):
    content = msg['content']
    msg_ids = sorted(set(content['msg_ids']))
    statusonly = content.get('status_only', False)
    pending = []
    completed = []
    content = dict(status='ok')
    content['pending'] = pending
    content['completed'] = completed
    buffers = []
    if not statusonly:
        try:
            matches = self.db.find_records(dict(msg_id={'$in': msg_ids}))
            records = {}
            for rec in matches:
                records[rec['msg_id']] = rec
        except Exception:
            content = error.wrap_exception()
            self.session.send(self.query, 'result_reply', content=content, parent=msg, ident=client_id)
            return
    else:
        records = {}
    for msg_id in msg_ids:
        if msg_id in self.pending:
            pending.append(msg_id)
        elif msg_id in self.all_completed:
            completed.append(msg_id)
            if not statusonly:
                (c, bufs) = self._extract_record(records[msg_id])
                content[msg_id] = c
                buffers.extend(bufs)
        elif msg_id in records:
            if rec['completed']:
                completed.append(msg_id)
                (c, bufs) = self._extract_record(records[msg_id])
                content[msg_id] = c
                buffers.extend(bufs)
            else:
                pending.append(msg_id)
        else:
            try:
                raise KeyError('No such message: ' + msg_id)
            except:
                content = error.wrap_exception()
            break
    self.session.send(self.query, 'result_reply', content=content, parent=msg, ident=client_id, buffers=buffers)

def user_agent():
    data = {'installer': {'name': 'pip', 'version': pip.__version__}, 'python': platform.python_version(), 'implementation': {'name': platform.python_implementation()}}
    if data['implementation']['name'] == 'CPython':
        data['implementation']['version'] = platform.python_version()
    elif data['implementation']['name'] == 'PyPy':
        if sys.pypy_version_info.releaselevel == 'final':
            pypy_version_info = sys.pypy_version_info[:3]
        else:
            pypy_version_info = sys.pypy_version_info
        data['implementation']['version'] = '.'.join([str(x) for x in pypy_version_info])
    elif data['implementation']['name'] == 'Jython':
        data['implementation']['version'] = platform.python_version()
    elif data['implementation']['name'] == 'IronPython':
        data['implementation']['version'] = platform.python_version()
    if sys.platform.startswith('linux'):
        distro = dict(filter(lambda x: x[1], zip(['name', 'version', 'id'], platform.linux_distribution())))
        libc = dict(filter(lambda x: x[1], zip(['lib', 'version'], platform.libc_ver())))
        if libc:
            distro['libc'] = libc
        if distro:
            data['distro'] = distro
    if sys.platform.startswith('darwin') and platform.mac_ver()[0]:
        data['distro'] = {'name': 'OS X', 'version': platform.mac_ver()[0]}
    if platform.system():
        data.setdefault('system', {})['name'] = platform.system()
    if platform.release():
        data.setdefault('system', {})['release'] = platform.release()
    if platform.machine():
        data['cpu'] = platform.machine()
    return '{data[installer][name]}/{data[installer][version]} {json}'.format(data=data, json=json.dumps(data, separators=(',', ':'), sort_keys=True))

