def loads(data, wrapper=dict):
    if not isinstance(data, str):
        raise TypeError('can only load a str as an ACF but got ' + type(data).__name__)
    parsed = wrapper()
    current_section = parsed
    sections = []
    lines = (line.strip() for line in data.splitlines())
    for line in lines:
        try:
            (key, value) = line.split(None, 1)
            key = key.replace('"', '').lstrip()
            value = value.replace('"', '').rstrip()
        except ValueError:
            if line == SECTION_START:
                current_section = _prepare_subsection(parsed, sections, wrapper)
            elif line == SECTION_END:
                sections.pop()
            else:
                sections.append(line.replace('"', ''))
            continue
        current_section[key] = value
    return parsed

def backup_file(self, file, dest_dir, copy_empty=False):
    if file.exists():
        if not copy_empty and file.is_empty():
            return None
        dest_dir.create()
        file.copy(dest_dir)
        return dest_dir + file.get_basefile()
    elif copy_empty:
        dest_dir = dest_dir + file.get_directory()
        dest_dir.create()
        dest_file = dest_dir + file.get_basefile()
        dest_file.touch()
        return dest_file
    else:
        return None

