def encode_span(self, span):
    json_span = {'traceId': span.trace_id, 'id': span.span_id}
    if span.name:
        json_span['name'] = span.name
    if span.parent_id:
        json_span['parentId'] = span.parent_id
    if span.timestamp:
        json_span['timestamp'] = int(span.timestamp * 1000000)
    if span.duration:
        json_span['duration'] = int(span.duration * 1000000)
    if span.shared is True:
        json_span['shared'] = True
    if span.kind and span.kind.value is not None:
        json_span['kind'] = span.kind.value
    if span.local_endpoint:
        json_span['localEndpoint'] = self._create_json_endpoint(span.local_endpoint, False)
    if span.remote_endpoint:
        json_span['remoteEndpoint'] = self._create_json_endpoint(span.remote_endpoint, False)
    if span.tags and len(span.tags) > 0:
        json_span['tags'] = span.tags
    if span.annotations:
        json_span['annotations'] = [{'timestamp': int(timestamp * 1000000), 'value': key} for (key, timestamp) in span.annotations.items()]
    encoded_span = json.dumps(json_span)
    return encoded_span

def run(self, dag):
    for node in dag.op_nodes(self.gate):
        if not node.op.definition:
            continue
        rule = node.op.definition
        decomposition = DAGCircuit()
        decomposition.add_qreg(rule[0][1][0][0])
        if rule[0][2]:
            decomposition.add_creg(rule[0][2][0][0])
        for inst in rule:
            decomposition.apply_operation_back(*inst)
        dag.substitute_node_with_dag(node, decomposition)
    return dag

def pick_peaks(nc, L=16):
    offset = nc.mean() / 20.0
    nc = filters.gaussian_filter1d(nc, sigma=4)
    th = filters.median_filter(nc, size=L) + offset
    peaks = []
    for i in range(1, nc.shape[0] - 1):
        if nc[i - 1] < nc[i] and nc[i] > nc[i + 1]:
            if nc[i] > th[i]:
                peaks.append(i)
    return peaks

def pprint(root, depth=0, space_unit='    ', *, source_len=0, file=None):
    spacing = space_unit * depth
    if isinstance(root, str):
        print('{0}terminal@(?): {1}'.format(spacing, root), file=file)
    else:
        if root.position is None:
            position = -1
        elif root.position < 0:
            position = source_len + root.position
        else:
            position = root.position
        if root.is_value:
            print('{0}{1}@({2}:{3}):\t{4}'.format(spacing, root.node_type, position, root.consumed, root.svalue), file=file)
        else:
            print('{0}{1}@({2}:{3}):'.format(spacing, root.node_type, position, root.consumed), file=file)
            for child in root.children:
                pprint(child, depth + 1, source_len=source_len, file=file)

def object_to_primitive(obj):
    if obj is None:
        return obj
    if isinstance(obj, (int, float, bool, str)):
        return obj
    if isinstance(obj, (list, frozenset, set)):
        return [object_to_primitive(x) for x in obj]
    if isinstance(obj, dict):
        return dict([(object_to_primitive(k), object_to_primitive(v)) for (k, v) in obj.items()])
    data = vars(obj)
    assert isinstance(data, dict)
    return object_to_primitive(data)

