def rank_within_group_by(self, group_by_cols, sort_cols, ascending=[], new_col_name='New_Rank_column', sort_cols_sorted=False):
    assert_is_type(group_by_cols, str, int, [str, int])
    if type(group_by_cols) != list:
        group_by_cols = [group_by_cols]
    if type(sort_cols) != list:
        sort_cols = [sort_cols]
    if type(ascending) != list:
        ascending = [ascending]
    ascendingI = [1] * len(sort_cols)
    for c in sort_cols:
        if self.type(c) not in ['enum', 'time', 'int', 'real']:
            raise H2OValueError('Sort by column: ' + str(c) + ' not of enum, time, int or real type')
    for c in group_by_cols:
        if self.type(c) not in ['enum', 'time', 'int', 'real']:
            raise H2OValueError('Group by column: ' + str(c) + ' not of enum, time, int or real type')
    if len(ascending) > 0:
        assert len(ascending) == len(sort_cols), 'Sorting direction must be specified for each sorted column.'
        for index in range(len(sort_cols)):
            ascendingI[index] = 1 if ascending[index] else -1
    finalSortedOrder = 0
    if sort_cols_sorted:
        finalSortedOrder = 1
    return H2OFrame._expr(expr=ExprNode('rank_within_groupby', self, group_by_cols, sort_cols, ascendingI, new_col_name, finalSortedOrder))

def read(self, input_stream, kmip_version=enums.KMIPVersion.KMIP_1_0):
    super(CheckResponsePayload, self).read(input_stream, kmip_version=kmip_version)
    local_stream = utils.BytearrayStream(input_stream.read(self.length))
    if self.is_tag_next(enums.Tags.UNIQUE_IDENTIFIER, local_stream):
        self._unique_identifier = primitives.TextString(tag=enums.Tags.UNIQUE_IDENTIFIER)
        self._unique_identifier.read(local_stream, kmip_version=kmip_version)
    if self.is_tag_next(enums.Tags.USAGE_LIMITS_COUNT, local_stream):
        self._usage_limits_count = primitives.LongInteger(tag=enums.Tags.USAGE_LIMITS_COUNT)
        self._usage_limits_count.read(local_stream, kmip_version=kmip_version)
    if self.is_tag_next(enums.Tags.CRYPTOGRAPHIC_USAGE_MASK, local_stream):
        self._cryptographic_usage_mask = primitives.Integer(tag=enums.Tags.CRYPTOGRAPHIC_USAGE_MASK)
        self._cryptographic_usage_mask.read(local_stream, kmip_version=kmip_version)
    if self.is_tag_next(enums.Tags.LEASE_TIME, local_stream):
        self._lease_time = primitives.Interval(tag=enums.Tags.LEASE_TIME)
        self._lease_time.read(local_stream, kmip_version=kmip_version)
    self.is_oversized(local_stream)

def locate(self, maximum_items=None, storage_status_mask=None, object_group_member=None, attributes=None):
    if maximum_items is not None:
        if not isinstance(maximum_items, six.integer_types):
            raise TypeError('maximum_items must be an integer')
    if storage_status_mask is not None:
        if not isinstance(storage_status_mask, six.integer_types):
            raise TypeError('storage_status_mask must be an integer')
    if object_group_member is not None:
        if not isinstance(object_group_member, enums.ObjectGroupMember):
            raise TypeError('object_group_member must be a ObjectGroupMemberenumeration')
    if attributes is not None:
        if not isinstance(attributes, list) or all((isinstance(item, cobjects.Attribute) for item in attributes)) is False:
            raise TypeError('attributes must be a list of attributes')
    result = self.proxy.locate(maximum_items, storage_status_mask, object_group_member, attributes)
    status = result.result_status.value
    if status == enums.ResultStatus.SUCCESS:
        return result.uuids
    else:
        reason = result.result_reason.value
        message = result.result_message.value
        raise exceptions.KmipOperationFailure(status, reason, message)

def convert(self, obj):
    if isinstance(obj, pobjects.SymmetricKey):
        return self._build_core_key(obj, secrets.SymmetricKey)
    elif isinstance(obj, secrets.SymmetricKey):
        return self._build_pie_key(obj, pobjects.SymmetricKey)
    elif isinstance(obj, pobjects.PublicKey):
        return self._build_core_key(obj, secrets.PublicKey)
    elif isinstance(obj, secrets.PublicKey):
        return self._build_pie_key(obj, pobjects.PublicKey)
    elif isinstance(obj, pobjects.PrivateKey):
        return self._build_core_key(obj, secrets.PrivateKey)
    elif isinstance(obj, secrets.PrivateKey):
        return self._build_pie_key(obj, pobjects.PrivateKey)
    elif isinstance(obj, pobjects.Certificate):
        return self._build_core_certificate(obj)
    elif isinstance(obj, secrets.Certificate):
        return self._build_pie_certificate(obj)
    elif isinstance(obj, pobjects.SecretData):
        return self._build_core_secret_data(obj)
    elif isinstance(obj, secrets.SecretData):
        return self._build_pie_secret_data(obj)
    elif isinstance(obj, pobjects.OpaqueObject):
        return self._build_core_opaque_object(obj)
    elif isinstance(obj, secrets.OpaqueObject):
        return self._build_pie_opaque_object(obj)
    else:
        raise TypeError('object type unsupported and cannot be converted')

