    if self._attestation_capability:
        self._attestation_capability.write(local_buffer, kmip_version=kmip_version)
    if kmip_version >= enums.KMIPVersion.KMIP_1_4:
        if self._batch_undo_capability:
            self._batch_undo_capability.write(local_buffer, kmip_version=kmip_version)
        if self._batch_continue_capability:
            self._batch_continue_capability.write(local_buffer, kmip_version=kmip_version)
    if self._unwrap_mode:
        self._unwrap_mode.write(local_buffer, kmip_version=kmip_version)
    if self._destroy_action:
        self._destroy_action.write(local_buffer, kmip_version=kmip_version)
    if self._shredding_algorithm:
        self._shredding_algorithm.write(local_buffer, kmip_version=kmip_version)
    if self._rng_mode:
        self._rng_mode.write(local_buffer, kmip_version=kmip_version)
    self.length = local_buffer.length()
    super(CapabilityInformation, self).write(output_buffer, kmip_version=kmip_version)
    output_buffer.write(local_buffer.buffer)

def direct_upload(request):
    if request.method == 'POST':
        try:
            form = YoutubeDirectUploadForm(request.POST, request.FILES)
            if form.is_valid():
                uploaded_video = form.save()
                api = Api()
                api.authenticate()
                video_entry = api.upload_direct(uploaded_video.file_on_server.path, 'Uploaded video from zuqqa')
                swf_url = video_entry.GetSwfUrl()
                youtube_url = video_entry.id.text
                url_parts = youtube_url.split('/')
                url_parts.reverse()
                video_id = url_parts[0]
                video = Video()
                video.user = request.user
                video.video_id = video_id
                video.title = 'tmp video'
                video.youtube_url = youtube_url
                video.swf_url = swf_url
                video.save()
                video_created.send(sender=video, video=video)
                uploaded_video.delete()
                return_only_data = request.GET.get('only_data')
                if return_only_data:
                    return HttpResponse(json.dumps({'video_id': video_id}), content_type='application/json')
                else:
                    try:
                        next_url = settings.YOUTUBE_UPLOAD_REDIRECT_URL
                    except AttributeError:
                        next_url = reverse('django_youtube.views.video', kwargs={'video_id': video_id})
                    return HttpResponseRedirect(next_url)
        except:
            import sys
            logger.error('Unexpected error: %s - %s' % (sys.exc_info()[0], sys.exc_info()[1]))
            return HttpResponse('error happened')
    form = YoutubeDirectUploadForm()
    if return_only_data:
        return HttpResponse(json.dumps({'error': 500}), content_type='application/json')
    else:
        return render_to_response('django_youtube/direct-upload.html', {'form': form}, context_instance=RequestContext(request))

def _srvc_check_hdf_properties(self, traj):
    for attr_name in HDF5StorageService.ATTR_LIST:
        try:
            config = traj.f_get('config.hdf5.' + attr_name).f_get()
            setattr(self, attr_name, config)
        except AttributeError:
            self._logger.debug('Could not find `%s` in traj config, using (default) value `%s`.' % (attr_name, str(getattr(self, attr_name))))
    for (attr_name, table_name) in HDF5StorageService.NAME_TABLE_MAPPING.items():
        try:
            if table_name in ('parameters', 'config'):
                table_name += '_overview'
            config = traj.f_get('config.hdf5.overview.' + table_name).f_get()
            setattr(self, attr_name, config)
        except AttributeError:
            self._logger.debug('Could not find `%s` in traj config, using (default) value `%s`.' % (table_name, str(getattr(self, attr_name))))
    for (attr_name, name) in HDF5StorageService.PR_ATTR_NAME_MAPPING.items():
        try:
            config = traj.f_get('config.hdf5.' + name).f_get()
            setattr(self, attr_name, config)
        except AttributeError:
            self._logger.debug('Could not find `%s` in traj config, using (default) value `%s`.' % (name, str(getattr(self, attr_name))))
    if (not self._overview_results_summary or not self._overview_derived_parameters_summary) and self._purge_duplicate_comments:
        raise RuntimeError('You chose to purge duplicate comments but disabled a summary table. You can only use the purging if you enable the summary tables.')
    self._filters = None

def _prm_load_parameter_or_result(self, instance, load_data=pypetconstants.LOAD_DATA, load_only=None, load_except=None, load_flags=None, with_links=False, recursive=False, max_depth=None, _hdf5_group=None):
    if load_data == pypetconstants.LOAD_NOTHING:
        return
    if _hdf5_group is None:
        _hdf5_group = self._all_get_node_by_name(instance.v_full_name)
    if load_data == pypetconstants.OVERWRITE_DATA:
        if instance.v_is_parameter and instance.v_locked:
            self._logger.debug('Parameter `%s` is locked, I will skip loading.' % instance.v_full_name)
            return
        instance.f_empty()
        instance.v_annotations.f_empty()
        instance.v_comment = ''
    self._all_load_skeleton(instance, _hdf5_group)
    instance._stored = True
    if isinstance(load_only, str):
        load_only = [load_only]
    if isinstance(load_except, str):
        load_except = [load_except]
    if load_data == pypetconstants.LOAD_SKELETON:
        self._node_processing_timer.signal_update()
        return
    elif load_only is not None:
        if load_except is not None:
            raise ValueError('Please use either `load_only` or `load_except` and not both at the same time.')
        elif instance.v_is_parameter and instance.v_locked:
            raise pex.ParameterLockedException('Parameter `%s` is locked, I will skip loading.' % instance.v_full_name)
        self._logger.debug('I am in load only mode, I will only load %s.' % str(load_only))
        load_only = set(load_only)
    elif load_except is not None:
        if instance.v_is_parameter and instance.v_locked:
            raise pex.ParameterLockedException('Parameter `%s` is locked, I will skip loading.' % instance.v_full_name)
        self._logger.debug('I am in load except mode, I will load everything except %s.' % str(load_except))
        load_except = set(load_except)
    elif not instance.f_is_empty():
        self._node_processing_timer.signal_update()
        return
    full_name = instance.v_full_name
    self._logger.debug('Loading data of %s' % full_name)
    load_dict = {}
    if load_flags is None:
        load_flags = {}
    try:
        instance_flags = instance._load_flags().copy()
    except AttributeError:
        instance_flags = {}
    instance_flags.update(load_flags)
    load_flags = instance_flags
    self._prm_load_into_dict(full_name=full_name, load_dict=load_dict, hdf5_group=_hdf5_group, instance=instance, load_only=load_only, load_except=load_except, load_flags=load_flags)
    if load_only is not None:
        if len(load_only) > 0:
            self._logger.warning('You marked %s for load only, but I cannot find these for `%s`' % (str(load_only), full_name))
    elif load_except is not None:
        if len(load_except) > 0:
            self._logger.warning('You marked `%s` for not loading, but these were not part of `%s` anyway.' % (str(load_except), full_name))
    if load_dict:
        try:
            instance._load(load_dict)
            if instance.v_is_parameter:
                instance.f_lock()
        except:
            self._logger.error('Error while reconstructing data of leaf `%s`.' % full_name)
            raise
    self._node_processing_timer.signal_update()

def get_message_definitions(self, msgid_or_symbol: str) -> list:
    if msgid_or_symbol[1:].isdigit():
        msgid_or_symbol = msgid_or_symbol.upper()
    for source in (self._alternative_names, self._messages_definitions):
        try:
            return [source[msgid_or_symbol]]
        except KeyError:
            pass
    error_msg = "No such message id or symbol '{msgid_or_symbol}'.".format(msgid_or_symbol=msgid_or_symbol)
    raise UnknownMessageError(error_msg)

def open(self, bus):
    bus = int(bus)
    path = '/dev/i2c-%d' % (bus,)
    if len(path) >= MAXPATH:
        raise OverflowError('Bus number is invalid.')
    try:
        self._fd = os.open(path, os.O_RDWR, 0)
    except OSError as e:
        raise IOError(e.errno)

def encode_arg(arg):
    arg_utf8 = utf8(arg)
    return ELEM_SEP.join([str(len(str(arg_utf8))), str(arg_utf8)])

