def merge_opt_params(self, method, kargs):
    for key in self.legal_params[method]:
        if not hasattr(self.opt, key) or getattr(self.opt, key) is None:
            continue
        if key in kargs and type(kargs[key]) == dict:
            assert type(getattr(self.opt, key)) == dict
            for (k, v) in getattr(self.opt, key).iteritems():
                kargs[key][k] = v
        else:
            kargs[key] = getattr(self.opt, key)
    return kargs

def dispose_orm():
    log.debug('Disposing DB connection pool (PID %s)', os.getpid())
    global engine
    global Session
    if Session:
        Session.remove()
        Session = None
    if engine:
        engine.dispose()
        engine = None

def send(self, peer, typename, data):

    def attempt_to_send(_):
        if peer not in self._connections:
            d = self._connect(peer)
            d.addCallback(attempt_to_send)
            return d
        else:
            conn = self._connections[peer][0]
            conn.send_packet(typename, data)
            return defer.succeed(None)
    d = attempt_to_send(None)
    self._ongoing_sends.add(d)

    def send_completed(result):
        if d in self._ongoing_sends:
            self._ongoing_sends.remove(d)
        return result
    d.addBoth(send_completed)
    return d

def shlex_quote(s):
    if is_py3:
        return quote(s)
    if not s:
        return "''"
    if _find_unsafe(s) is None:
        return s
    return "'" + s.replace("'", '\'"\'"\'') + "'"

